# Internal teaching capsule: taidyverse
# This file contains the step definitions for the French-language taidyverse capsule.

taidyverse_steps <- function() {
  steps <-
    list(donnees = structure(list(id = "donnees", title = "Le Grand D'epart",
                                  section = "stat", objective = "D'ecouvrir le terrain de jeu : les variables quantitatives, qualitatives et textuelle du questionnaire.",
                                  text = NULL, code = "# ============================================================\n# Case 1 : pr'esenter le questionnaire\n# ============================================================\n\n# Objectif de cette case :\n# comprendre le jeu de donn'ees utilis'e dans tout le tutoriel.\n#\n# Le questionnaire n est plus simul'e ici.\n# Il est suppos'e d'ej`a disponible dans le package.\n#\n# Il contient :\n# - des variables d 'evaluation du produit ;\n# - des variables d'ecrivant le rapport `a l alimentation ;\n# - des variables qualitatives de contexte ;\n# - une variable textuelle ;\n# - des variables actives qui serviront ensuite `a construire une typologie.\n\n# ------------------------------------------------------------\n# 1. R'ecup'erer l objet questionnaire\n# ------------------------------------------------------------\n\n# Dans le package, le jeu de donn'ees pourra ^etre charg'e sous le nom :\n# questionnaire_alimentaire_typologie_textes\n#\n# Pour simplifier le reste du tutoriel, on cr'ee ou v'erifie l objet\n# questionnaire, qui sera le nom utilis'e dans toutes les cases suivantes.\n\nif (!exists('questionnaire')) {\n\n  if (exists('questionnaire_alimentaire_typologie_textes')) {\n\n    questionnaire <- questionnaire_alimentaire_typologie_textes\n\n  } else if (requireNamespace('SeRiouS', quietly = TRUE)) {\n\n    questionnaire <- SeRiouS::questionnaire_alimentaire_typologie_textes\n\n  } else {\n\n    stop(\n      'Aucun objet questionnaire disponible. ',\n      'Le jeu de donn'ees questionnaire_alimentaire_typologie_textes doit ^etre int'egr'e au package SeRiouS.'\n    )\n  }\n}\n\ncat('\\n============================================================\\n')\ncat('1. Jeu de donn'ees utilis'e\\n')\ncat('============================================================\\n')\ncat('Objet utilis'e : questionnaire\\n')\ncat('Nombre de r'epondants : ', nrow(questionnaire), '\\n', sep = '')\ncat('Nombre de variables : ', ncol(questionnaire), '\\n', sep = '')\n\n\n# ------------------------------------------------------------\n# 2. S'ecuriser les types de variables\n# ------------------------------------------------------------\n\n# Certaines variables doivent ^etre trait'ees comme qualitatives.\n# On les force donc en factor si elles existent dans le jeu de donn'ees.\n\nvariables_qualitatives <- c(\n  'type_produit',\n  'budget_contraint',\n  'sexe',\n  'age_classe',\n  'lieu_achat',\n  'profil_alim'\n)\n\nvariables_qualitatives <- intersect(\n  variables_qualitatives,\n  names(questionnaire)\n)\n\nquestionnaire[variables_qualitatives] <- lapply(\n  questionnaire[variables_qualitatives],\n  factor\n)\n\nif ('commentaire' %in% names(questionnaire)) {\n  questionnaire$commentaire <- as.character(questionnaire$commentaire)\n}\n\n# cat('\\n============================================================\\n')\n# cat('2. Types de variables v'erifi'es\\n')\n# cat('============================================================\\n')\n# cat('Variables qualitatives converties en factor :\\n')\n# print(variables_qualitatives)\n#\n# if ('commentaire' %in% names(questionnaire)) {\n#   cat('\\nVariable textuelle : commentaire\\n')\n# }\n\n\n# ------------------------------------------------------------\n# 3. Construire un dictionnaire simplifi'e des variables\n# ------------------------------------------------------------\n\ndictionnaire_variables <- data.frame(\n  variable = c(\n    'id',\n    'satisfaction',\n    'intention_achat',\n    'prix_percu',\n    'plaisir',\n    'naturalite',\n    'confiance',\n    'ancrage_local',\n    'usage_numerique',\n    'sensibilite_env',\n    'attention_prix',\n    'contrainte_temps',\n    'cuisine_maison',\n    'lecture_labels',\n    'achat_local',\n    'ouverture_innovation',\n    'usage_appli_alim',\n    'preoccupation_sante',\n    'autonomie_alimentaire',\n    'confiance_labels',\n    'type_produit',\n    'budget_contraint',\n    'sexe',\n    'age_classe',\n    'lieu_achat',\n    'profil_alim',\n    'commentaire'\n  ),\n  famille = c(\n    'Identifiant',\n    'Evaluation du produit',\n    'Evaluation du produit',\n    'Evaluation du produit',\n    'Evaluation du produit',\n    'Evaluation du produit',\n    'Evaluation du produit',\n    'Evaluation du produit',\n    'Rapport `a l information',\n    'Rapport `a l environnement',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Variables actives de typologie',\n    'Contexte produit',\n    'Contexte r'epondant',\n    'Contexte r'epondant',\n    'Contexte r'epondant',\n    'Contexte d achat',\n    'Profil alimentaire explicite',\n    'Texte libre'\n  ),\n  role_dans_le_tutoriel = c(\n    'rep'erer les individus',\n    'variable r'eponse possible',\n    'variable r'eponse pour la r'egression',\n    'variable explicative et descriptive',\n    'variable explicative',\n    'variable explicative et descriptive',\n    'variable explicative',\n    'variable explicative et descriptive',\n    'variable descriptive',\n    'variable descriptive',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'variable active pour ACP / typologie',\n    'facteur pour ANOVA',\n    'facteur pour ANOVA',\n    'variable illustrative',\n    'variable illustrative',\n    'variable illustrative',\n    'variable qualitative pour catdes / nail_catdes',\n    'variable textuelle pour le flow NaileR'\n  ),\n  stringsAsFactors = FALSE\n)\n\n# On ne garde dans le dictionnaire que les variables r'eellement pr'esentes.\ndictionnaire_variables <- dictionnaire_variables[\n  dictionnaire_variables$variable %in% names(questionnaire),\n]\n\n# cat('\\n============================================================\\n')\n# cat('3. Dictionnaire simplifi'e des variables\\n')\n# cat('============================================================\\n')\n# cat('Objet cr'e'e : dictionnaire_variables\\n')\n# print(dictionnaire_variables, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 4. V'erifier la structure R du questionnaire\n# ------------------------------------------------------------\n\nstructure_variables <- data.frame(\n  variable = names(questionnaire),\n  classe_R = vapply(questionnaire, function(x) class(x)[1], character(1)),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('2. Structure R du questionnaire\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : structure_variables\\n')\nprint(structure_variables, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 5. Pr'esenter les variables cl'es du tutoriel\n# ------------------------------------------------------------\n\nvariables_cles <- data.frame(\n  etape_du_tutoriel = c(\n    'R'egression lin'eaire',\n    'ANOVA',\n    'condes()',\n    'catdes() / nail_catdes()',\n    'ACP + HCPC',\n    'Flow textuel NaileR'\n  ),\n  variables_utilisees = c(\n    'intention_achat ~ satisfaction + prix_percu',\n    'satisfaction ~ type_produit * budget_contraint',\n    'intention_achat d'ecrite par les autres variables',\n    'profil_alim d'ecrit par les autres variables',\n    'variables actives de typologie',\n    'classe_hcpc + commentaire'\n  ),\n  objectif = c(\n    'mod'eliser une intention d achat',\n    'tester des effets de facteurs et une interaction',\n    'd'ecrire une variable quantitative',\n    'd'ecrire une variable qualitative',\n    'construire une classe latente',\n    'interpr'eter les classes `a partir des verbatims'\n  ),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('3. Variables cl'es pour la suite du plateau\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : variables_cles\\n')\nprint(variables_cles, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 6. V'erifier les variables actives pr'evues pour la typologie\n# ------------------------------------------------------------\n\nvariables_typologie <- c(\n  'attention_prix',\n  'contrainte_temps',\n  'cuisine_maison',\n  'lecture_labels',\n  'achat_local',\n  'ouverture_innovation',\n  'usage_appli_alim',\n  'preoccupation_sante',\n  'autonomie_alimentaire',\n  'confiance_labels'\n)\n\nvariables_typologie_presentes <- intersect(\n  variables_typologie,\n  names(questionnaire)\n)\n\n# cat('\\n============================================================\\n')\n# cat('6. Variables actives pr'evues pour la typologie\\n')\n# cat('============================================================\\n')\n# cat('Objet cr'e'e : variables_typologie\\n')\n# print(variables_typologie_presentes)\n\nif (length(variables_typologie_presentes) < length(variables_typologie)) {\n  cat('\\nAttention : certaines variables de typologie sont absentes du questionnaire.\\n')\n  cat('Variables attendues mais absentes :\\n')\n  print(setdiff(variables_typologie, variables_typologie_presentes))\n}\n\n\n# ------------------------------------------------------------\n# 7. Apercu du questionnaire\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('4. Apercu des premi`eres lignes\\n')\ncat('============================================================\\n')\nprint(head(questionnaire, 3))\n\n\n# ------------------------------------------------------------\n# 8. Apercu de la variable textuelle\n# ------------------------------------------------------------\n\nif ('commentaire' %in% names(questionnaire)) {\n\n  cat('\\n============================================================\\n')\n  cat('5. Apercu des commentaires libres\\n')\n  cat('============================================================\\n')\n  cat('Nombre de verbatims : ', length(questionnaire$commentaire), '\\n', sep = '')\n  cat('\\nExemples :\\n')\n  cat(paste('-', head(unique(questionnaire$commentaire), 6), collapse = '\\n'))\n  cat('\\n')\n}\n\n\n# ------------------------------------------------------------\n# 9. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e p'edagogique\\n')\ncat('============================================================\\n')\ncat('Le questionnaire est le fil rouge du tutoriel.\\n')\ncat('Il contient des variables explicites, un profil alimentaire calcul'e,\\n')\ncat('des variables pour construire une typologie,\\n')\ncat('et une variable textuelle.\\n')\ncat('\\n')\ncat('La suite du plateau va montrer comment passer :\\n')\ncat('- des analyses simples ;\\n')\ncat('- aux sorties FactoMineR ;\\n')\ncat('- aux prompts ;\\n')\ncat('- puis `a la compr'ehension des classes latentes.\\n')",
                                  code_display = "# Dimensions du questionnaire\nnrow(questionnaire)\nncol(questionnaire)\n\n# D'ecrire la structure R du questionnaire\nstructure_variables <- data.frame(\n  variable = names(questionnaire),\n  classe_R = vapply(questionnaire, function(x) class(x)[1], character(1)),\n  stringsAsFactors = FALSE\n)\n\n# Identifier les variables cl'es du tutoriel\nvariables_cles <- data.frame(\n  etape_du_tutoriel = c(\n    'R'egression lin'eaire',\n    'ANOVA',\n    'condes()',\n    'catdes() / nail_catdes()',\n    'ACP + HCPC',\n    'Flow textuel NaileR'\n  ),\n  variables_utilisees = c(\n    'intention_achat ~ satisfaction + prix_percu',\n    'satisfaction ~ type_produit * budget_contraint',\n    'intention_achat d'ecrite par les autres variables',\n    'profil_alim d'ecrit par les autres variables',\n    'variables actives de typologie',\n    'classe_hcpc + commentaire'\n  ),\n  objectif = c(\n    'mod'eliser une intention d achat',\n    'tester des effets de facteurs et une interaction',\n    'd'ecrire une variable quantitative',\n    'd'ecrire une variable qualitative',\n    'construire une classe latente',\n    'interpr'eter les classes `a partir des verbatims'\n  ),\n  stringsAsFactors = FALSE\n)\n\n# Apercu du questionnaire et des commentaires libres\nhead(questionnaire, 3)\n\nif ('commentaire' %in% names(questionnaire)) {\n  head(unique(questionnaire$commentaire), 6)\n}",
                                  expected_output = "Une vision structur'ee des donn'ees et la cr'eation de l'objet de base questionnaire",
                                  transition = "Les bases sont pos'ees, il est temps de partir en reconnaissance pour explorer visuellement ces variables.",
                                  outputs = "console", question = "Quel objet contient le questionnaire utilis'e dans le tutoriel ?",
                                  expected_answer = "questionnaire", validator = NULL, pdf = "questionnaire_SeRiouS_description.pdf",
                                  pdf_on_run = NULL, next_steps = "exploration", prerequisites = character(0),
                                  concepts = character(0), layout = list(x = 0, y = 0)), class = "serious_step"),
         exploration = structure(list(id = "exploration", title = "L'Exploration",
                                      section = "stat", objective = "Inspecter la distribution des variables et rep'erer les premi`eres relations visuellement.",
                                      text = NULL, code = "# ============================================================\n# Case 2 : explorer rapidement les donn'ees\n# ============================================================\n\n# Objectif de cette case :\n# produire une premi`ere description du jeu de donn'ees\n\n# ------------------------------------------------------------\n# 1. Identifier les variables quantitatives\n# ------------------------------------------------------------\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\n    call. = FALSE\n  )\n}\n\nvariables_quanti_exploration <- setdiff(\n  names(questionnaire)[vapply(questionnaire, is.numeric, logical(1))],\n  'id'\n)\n\ncat('\\n============================================================\\n')\ncat('1. Variables quantitatives identifi'ees\\n')\ncat('============================================================\\n')\nprint(variables_quanti_exploration)\n\n\n# ------------------------------------------------------------\n# 2. Construire un r'esum'e des variables quantitatives\n# ------------------------------------------------------------\n\nresume_quanti <- data.frame(\n  variable = variables_quanti_exploration,\n  min = vapply(\n    questionnaire[variables_quanti_exploration],\n    min,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  q1 = vapply(\n    questionnaire[variables_quanti_exploration],\n    function(x) quantile(x, 0.25, na.rm = TRUE),\n    numeric(1)\n  ),\n  mediane = vapply(\n    questionnaire[variables_quanti_exploration],\n    median,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  moyenne = vapply(\n    questionnaire[variables_quanti_exploration],\n    mean,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  q3 = vapply(\n    questionnaire[variables_quanti_exploration],\n    function(x) quantile(x, 0.75, na.rm = TRUE),\n    numeric(1)\n  ),\n  max = vapply(\n    questionnaire[variables_quanti_exploration],\n    max,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  row.names = NULL\n)\n\nresume_quanti[, -1] <- round(resume_quanti[, -1], 2)\n\ncat('\\n============================================================\\n')\ncat('2. R'esum'e des variables quantitatives\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : resume_quanti\\n')\nprint(resume_quanti, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 3. Identifier les variables qualitatives\n# ------------------------------------------------------------\n\nvariables_quali_exploration <- names(questionnaire)[\n  vapply(questionnaire, is.factor, logical(1))\n]\n\ncat('\\n============================================================\\n')\ncat('3. Variables qualitatives identifi'ees\\n')\ncat('============================================================\\n')\nprint(variables_quali_exploration)\n\n\n# ------------------------------------------------------------\n# 4. Construire un r'esum'e des variables qualitatives\n# ------------------------------------------------------------\n\nresume_quali <- do.call(\n  rbind,\n  lapply(variables_quali_exploration, function(v) {\n    tab <- table(questionnaire[[v]], useNA = 'ifany')\n\n    data.frame(\n      variable = v,\n      modalite = names(tab),\n      effectif = as.integer(tab),\n      row.names = NULL\n    )\n  })\n)\n\ncat('\\n============================================================\\n')\ncat('4. R'esum'e des variables qualitatives\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : resume_quali\\n')\nprint(resume_quali, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 5. Explorer la variable textuelle\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('5. Variable textuelle\\n')\ncat('============================================================\\n')\ncat('Variable : commentaire\\n')\ncat('Nombre de verbatims : ', length(questionnaire$commentaire), '\\n', sep = '')\ncat('Nombre de verbatims uniques : ', length(unique(questionnaire$commentaire)), '\\n', sep = '')\ncat('Exemples :\\n')\ncat(paste('-', head(unique(questionnaire$commentaire), 5), collapse = '\\n'))\ncat('\\n')\n\n\n# ------------------------------------------------------------\n# 6. Produire deux graphiques exploratoires\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('6. Graphiques exploratoires\\n')\ncat('============================================================\\n')\ncat('Graphique 1 : distribution de intention_achat\\n')\ncat('Graphique 2 : satisfaction selon type_produit\\n')\n\nop <- par(mfrow = c(1, 2))\n\nhist(\n  questionnaire$intention_achat,\n  main = 'Intention d achat',\n  xlab = 'Score',\n  col = 'grey80',\n  border = 'white'\n)\n\nboxplot(\n  satisfaction ~ type_produit,\n  data = questionnaire,\n  main = 'Satisfaction selon produit',\n  xlab = 'Groupe produit',\n  ylab = 'Satisfaction',\n  col = 'grey85'\n)\n\npar(op)\n\n\n# ------------------------------------------------------------\n# 7. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- variables_quanti_exploration : noms des variables quantitatives\\n')\ncat('- resume_quanti : r'esum'e num'erique\\n')\ncat('- variables_quali_exploration : noms des variables qualitatives\\n')\ncat('- resume_quali : effectifs par modalit'e\\n')",
                                      code_display = "# Identifier les variables quantitatives\nvariables_quanti_exploration <- setdiff(\n  names(questionnaire)[vapply(questionnaire, is.numeric, logical(1))],\n  'id'\n)\n\nvariables_quanti_exploration\n\n# Construire un r'esum'e des variables quantitatives\nresume_quanti <- data.frame(\n  variable = variables_quanti_exploration,\n  min = vapply(\n    questionnaire[variables_quanti_exploration],\n    min,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  q1 = vapply(\n    questionnaire[variables_quanti_exploration],\n    function(x) quantile(x, 0.25, na.rm = TRUE),\n    numeric(1)\n  ),\n  mediane = vapply(\n    questionnaire[variables_quanti_exploration],\n    median,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  moyenne = vapply(\n    questionnaire[variables_quanti_exploration],\n    mean,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  q3 = vapply(\n    questionnaire[variables_quanti_exploration],\n    function(x) quantile(x, 0.75, na.rm = TRUE),\n    numeric(1)\n  ),\n  max = vapply(\n    questionnaire[variables_quanti_exploration],\n    max,\n    numeric(1),\n    na.rm = TRUE\n  ),\n  row.names = NULL\n)\n\nresume_quanti[, -1] <- round(resume_quanti[, -1], 2)\n\nresume_quanti\n\n# Identifier les variables qualitatives\nvariables_quali_exploration <- names(questionnaire)[\n  vapply(questionnaire, is.factor, logical(1))\n]\n\nvariables_quali_exploration\n\n# Construire un r'esum'e des variables qualitatives\nresume_quali <- do.call(\n  rbind,\n  lapply(variables_quali_exploration, function(v) {\n    tab <- table(questionnaire[[v]], useNA = 'ifany')\n\n    data.frame(\n      variable = v,\n      modalite = names(tab),\n      effectif = as.integer(tab),\n      row.names = NULL\n    )\n  })\n)\n\nresume_quali\n\n# Explorer la variable textuelle\nlength(questionnaire$commentaire)\nlength(unique(questionnaire$commentaire))\nhead(unique(questionnaire$commentaire), 5)\n\n# Produire deux graphiques exploratoires\nop <- par(mfrow = c(1, 2))\n\nhist(\n  questionnaire$intention_achat,\n  main = 'Intention d achat',\n  xlab = 'Score',\n  col = 'grey80',\n  border = 'white'\n)\n\nboxplot(\n  satisfaction ~ type_produit,\n  data = questionnaire,\n  main = 'Satisfaction selon produit',\n  xlab = 'Groupe produit',\n  ylab = 'Satisfaction',\n  col = 'grey85'\n)\n\npar(op)",
                                      expected_output = "Des r'esum'es statistiques cl'es (resume_quanti, resume_quali) et deux graphiques.",
                                      transition = "L'exploration visuelle termin'ee, nous pouvons entrer dans l'atelier pour mod'eliser ces relations.",
                                      outputs = c("console", "plot"), question = "Combien de lignes contient le jeu de donn'ees `questionnaire` ?",
                                      expected_answer = NULL, validator = function (answer,
                                                                                    envir)
                                      {
                                        if (!exists("questionnaire", envir = envir))
                                          return(FALSE)
                                        suppressWarnings(as.numeric(answer) == nrow(get("questionnaire",
                                                                                        envir = envir)))
                                      }, pdf = NULL, pdf_on_run = NULL, next_steps = "linearmodel",
                                      prerequisites = character(0), concepts = character(0),
                                      layout = list(x = 260, y = 0)), class = "serious_step"),
         linearmodel = structure(list(id = "linearmodel", title = "L'Atelier Lin'eaire",
                                      section = "stat", objective = "Ajuster une premi`ere r'egression lin'eaire avec FactoMineR::LinearModel() pour mod'eliser une intention d'achat.",
                                      text = NULL, code = "# ============================================================\n# Case 3 : r'egression lin'eaire avec LinearModel()\n# ============================================================\n\n# Objectif de cette case :\n# expliquer une variable quantitative Y par deux variables explicatives.\n# Ici : intention_achat est expliqu'ee par satisfaction et prix_percu.\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\n    call. = FALSE\n  )\n}\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop('Installe FactoMineR : install.packages(\"FactoMineR\")')\n}\n\n\n# ------------------------------------------------------------\n# 1. D'efinir la formule du mod`ele\n# ------------------------------------------------------------\n\nformule_lm <- intention_achat ~ satisfaction + prix_percu\n\ncat('\\n============================================================\\n')\ncat('1. Formule du mod`ele lin'eaire\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : formule_lm\\n')\nprint(formule_lm)\n\ncat('\\nLecture :\\n')\ncat('- Y : intention_achat\\n')\ncat('- X : satisfaction et prix_percu\\n')\n\n\n# ------------------------------------------------------------\n# 2. Ajuster le mod`ele avec FactoMineR::LinearModel()\n# ------------------------------------------------------------\n\nres_lm_fm <- FactoMineR::LinearModel(\n  formule_lm,\n  data = questionnaire,\n  selection = 'none'\n)\n\ncat('\\n============================================================\\n')\ncat('2. Mod`ele ajust'e avec FactoMineR::LinearModel()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_lm_fm\\n')\ncat('Le mod`ele complet n est pas imprim'e brutalement ici.\\n')\ncat('On affiche un apercu lisible ; les sous-objets seront r'ecup'er'es dans la case 5.\\n')\n\n\n# ------------------------------------------------------------\n# 3. Afficher les r'esultats principaux avec des titres\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('3. Test global des effets : res_lm_fm$Ftest\\n')\ncat('============================================================\\n')\nprint(res_lm_fm$Ftest)\n\ncat('\\n============================================================\\n')\ncat('4. Coefficients du mod`ele : res_lm_fm$Ttest\\n')\ncat('============================================================\\n')\nprint(res_lm_fm$Ttest)\n\n\n# ------------------------------------------------------------\n# 4. Graphique exploratoire de la relation principale\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('5. Graphique\\n')\ncat('============================================================\\n')\ncat('Nuage de points : intention_achat en fonction de satisfaction.\\n')\ncat('La droite affich'ee est une r'egression simple illustrative.\\n')\n\nplot(\n  questionnaire$satisfaction,\n  questionnaire$intention_achat,\n  pch = 16,\n  col = 'grey40',\n  xlab = 'Satisfaction',\n  ylab = 'Intention d achat',\n  main = 'Intention d achat ~ Satisfaction'\n)\n\nabline(\n  lm(intention_achat ~ satisfaction, data = questionnaire),\n  lwd = 2\n)\n\n\n# ------------------------------------------------------------\n# 5. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- formule_lm : formule du mod`ele lin'eaire\\n')\ncat('- res_lm_fm : r'esultat complet de FactoMineR::LinearModel()\\n')\ncat('\\n')\ncat('Ces objets seront utilis'es pour r'ecup'erer les sorties et construire un prompt.\\n')",
                                      code_display = "# V'erifier que FactoMineR est disponible\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop('Installe FactoMineR : install.packages(\"FactoMineR\")')\n}\n\n# D'efinir la formule du mod`ele lin'eaire\nformule_lm <- intention_achat ~ satisfaction + prix_percu\n\nformule_lm\n\n# Ajuster le mod`ele avec FactoMineR::LinearModel()\nres_lm_fm <- FactoMineR::LinearModel(\n  formule_lm,\n  data = questionnaire,\n  selection = 'none'\n)\n\n# Examiner les r'esultats principaux\nres_lm_fm$Ftest\nres_lm_fm$Ttest\n\n# Graphique exploratoire de la relation entre satisfaction et intention d achat\nplot(\n  questionnaire$satisfaction,\n  questionnaire$intention_achat,\n  pch = 16,\n  col = 'grey40',\n  xlab = 'Satisfaction',\n  ylab = 'Intention d achat',\n  main = 'Intention d achat ~ Satisfaction'\n)\n\nabline(\n  lm(intention_achat ~ satisfaction, data = questionnaire),\n  lwd = 2\n)",
                                      expected_output = "Des objets R, `formule_lm` et `res_lm_fm`, contenant notamment F-tests, T-tests et r'esum'e du mod`ele.",
                                      transition = "Apr`es la droite de r'egression, int'eressons-nous au croisement de facteurs avec l'analyse de variance.",
                                      outputs = c("console", "plot"), question = "Quelle fonction de FactoMineR est utilis'ee pour la r'egression lin'eaire ?",
                                      expected_answer = "LinearModel", validator = NULL, pdf = NULL,
                                      pdf_on_run = NULL, next_steps = "aovsum", prerequisites = character(0),
                                      concepts = character(0), layout = list(x = 520, y = 0)), class = "serious_step"),
         aovsum = structure(list(id = "aovsum", title = "Le Carrefour de la Variance",
                                 section = "stat", objective = "Tester l'effet de variables cat'egorielles et de leurs interactions sur la satisfaction `a l'aide de la fonction FactoMineR::AovSum().",
                                 text = NULL, code = "# ============================================================\n# Case 4 : ANOVA avec AovSum()\n# ============================================================\n\n# Objectif de cette case :\n# expliquer une variable quantitative par des facteurs qualitatifs\n# et examiner une interaction entre facteurs.\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\n    call. = FALSE\n  )\n}\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop('Installe FactoMineR : install.packages(\"FactoMineR\")')\n}\n\n\n# ------------------------------------------------------------\n# 1. D'efinir la formule de l ANOVA\n# ------------------------------------------------------------\n\nformule_aov <- satisfaction ~ type_produit * budget_contraint\n\ncat('\\n============================================================\\n')\ncat('1. Formule de l ANOVA\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : formule_aov\\n')\nprint(formule_aov)\n\ncat('\\nLecture :\\n')\ncat('- Y : satisfaction\\n')\ncat('- Facteur 1 : type_produit\\n')\ncat('- Facteur 2 : budget_contraint\\n')\ncat('- Interaction : type_produit:budget_contraint\\n')\n\n\n# ------------------------------------------------------------\n# 2. Ajuster l ANOVA avec FactoMineR::AovSum()\n# ------------------------------------------------------------\n\nres_aovsum <- FactoMineR::AovSum(\n  formule_aov,\n  data = questionnaire\n)\n\ncat('\\n============================================================\\n')\ncat('2. ANOVA ajust'ee avec FactoMineR::AovSum()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_aovsum\\n')\ncat('Le r'esultat complet n est pas imprim'e brutalement ici.\\n')\ncat('On affiche un apercu lisible ; les sous-objets seront r'ecup'er'es dans la case 5.\\n')\n\n\n# ------------------------------------------------------------\n# 3. Afficher les r'esultats principaux avec des titres\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('3. Effets principaux et interaction : res_aovsum$Ftest\\n')\ncat('============================================================\\n')\nprint(res_aovsum$Ftest)\n\ncat('\\n============================================================\\n')\ncat('4. Coefficients et contrastes : res_aovsum$Ttest\\n')\ncat('============================================================\\n')\nprint(res_aovsum$Ttest)\n\n\n# ------------------------------------------------------------\n# 4. Graphique d interaction\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('5. Graphique d interaction\\n')\ncat('============================================================\\n')\ncat('On visualise la satisfaction moyenne selon le budget et le type de produit.\\n')\n\ninteraction.plot(\n  x.factor = questionnaire$budget_contraint,\n  trace.factor = questionnaire$type_produit,\n  response = questionnaire$satisfaction,\n  xlab = 'Budget contraint',\n  ylab = 'Satisfaction moyenne',\n  trace.label = 'Produit',\n  main = 'Interaction produit x budget'\n)\n\n\n# ------------------------------------------------------------\n# 5. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- formule_aov : formule de l ANOVA\\n')\ncat('- res_aovsum : r'esultat complet de FactoMineR::AovSum()\\n')\ncat('\\n')\ncat('Ces objets seront utilis'es pour r'ecup'erer les sorties et construire un prompt.\\n')",
                                 code_display = "# V'erifier que FactoMineR est disponible\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop('Installe FactoMineR : install.packages(\"FactoMineR\")')\n}\n\n# D'efinir la formule de l ANOVA\nformule_aov <- satisfaction ~ type_produit * budget_contraint\n\nformule_aov\n\n# Ajuster l ANOVA avec FactoMineR::AovSum()\nres_aovsum <- FactoMineR::AovSum(\n  formule_aov,\n  data = questionnaire\n)\n\n# Examiner les r'esultats principaux\nres_aovsum$Ftest\nres_aovsum$Ttest\n\n# Visualiser l interaction entre type de produit et contrainte budg'etaire\ninteraction.plot(\n  x.factor = questionnaire$budget_contraint,\n  trace.factor = questionnaire$type_produit,\n  response = questionnaire$satisfaction,\n  xlab = 'Budget contraint',\n  ylab = 'Satisfaction moyenne',\n  trace.label = 'Produit',\n  main = 'Interaction produit x budget'\n)",
                                 expected_output = "Deux objets R, `formule_aov` et `res_aovsum`, avec les F-tests et T-tests de l'ANOVA.",
                                 transition = "Lire les r'esultats dans la console ne suffit plus : il faut maintenant capturer ces sorties pour les exploiter.",
                                 outputs = c("console", "plot"), question = "Quelle fonction de FactoMineR est utilis'ee pour l'analyse de la variance ?",
                                 expected_answer = "AovSum", validator = NULL, pdf = NULL,
                                 pdf_on_run = NULL, next_steps = "recuperer_sorties",
                                 prerequisites = character(0), concepts = character(0),
                                 layout = list(x = 780, y = 0)), class = "serious_step"),
         recuperer_sorties = structure(list(id = "recuperer_sorties",
                                            title = "La Zone de Capture", section = "r_sorties",
                                            objective = "Extraire et sauvegarder les sorties statistiques (tests, coefficients) dans des objets R manipulables.",
                                            text = NULL, code = "# ============================================================\n# Case 5 : r'ecup'erer les sorties\n# ============================================================\n\n# Objectif de cette case :\n# passer d'une sortie affich'ee dans la console\n# `a des objets R que l'on pourra r'eutiliser ensuite.\n\n# ------------------------------------------------------------\n# 1. Inspecter les objets retourn'es par FactoMineR\n# ------------------------------------------------------------\n\nif (!exists('res_lm_fm')) {\n  stop(\n    'L objet res_lm_fm est absent. Ex'ecute d abord la case 3.',\n    call. = FALSE\n  )\n}\n\nif (!exists('res_aovsum')) {\n  stop(\n    'L objet res_aovsum est absent. Ex'ecute d abord la case 4.',\n    call. = FALSE\n  )\n}\n\ncat('\\n============================================================\\n')\ncat('1. Que contient l objet res_lm_fm ?\\n')\ncat('Commande : names(res_lm_fm)\\n')\ncat('============================================================\\n')\nprint(names(res_lm_fm))\n\ncat('\\n============================================================\\n')\ncat('2. Que contient l objet res_aovsum ?\\n')\ncat('Commande : names(res_aovsum)\\n')\ncat('============================================================\\n')\nprint(names(res_aovsum))\n\n\n# ------------------------------------------------------------\n# 2. Extraire les sorties importantes de LinearModel()\n# ------------------------------------------------------------\n\nlm_ftest <- res_lm_fm$Ftest\nlm_ttest <- res_lm_fm$Ttest\nlm_resume <- res_lm_fm$lmResult\n\n\n# ------------------------------------------------------------\n# 3. Extraire les sorties importantes de AovSum()\n# ------------------------------------------------------------\n\naov_ftest <- res_aovsum$Ftest\naov_ttest <- res_aovsum$Ttest\n\n\n# ------------------------------------------------------------\n# 4. Afficher les objets extraits avec des titres explicites\n# ------------------------------------------------------------\n\nafficher_sortie <- function(titre, commande, objet) {\n  cat('\\n============================================================\\n')\n  cat(titre, '\\n')\n  cat('Objet cr'e'e : ', commande, '\\n', sep = '')\n  cat('============================================================\\n')\n  print(objet)\n}\n\nafficher_sortie(\n  titre = 'LinearModel : test global des effets - Ftest',\n  commande = 'lm_ftest <- res_lm_fm$Ftest',\n  objet = lm_ftest\n)\n\nafficher_sortie(\n  titre = 'LinearModel : coefficients du mod`ele - Ttest',\n  commande = 'lm_ttest <- res_lm_fm$Ttest',\n  objet = lm_ttest\n)\n\nafficher_sortie(\n  titre = 'AovSum : effets principaux et interaction - Ftest',\n  commande = 'aov_ftest <- res_aovsum$Ftest',\n  objet = aov_ftest\n)\n\nafficher_sortie(\n  titre = 'AovSum : coefficients et contrastes - Ttest',\n  commande = 'aov_ttest <- res_aovsum$Ttest',\n  objet = aov_ttest\n)\n\n\n# ------------------------------------------------------------\n# 5. Capturer les sorties compl`etes sous forme de texte\n# ------------------------------------------------------------\n\ntexte_linearmodel <- paste(\n  capture.output(print(res_lm_fm)),\n  collapse = '\\n'\n)\n\ntexte_aovsum <- paste(\n  capture.output(print(res_aovsum)),\n  collapse = '\\n'\n)\n\n\n# ------------------------------------------------------------\n# 6. Afficher un apercu des textes captur'es\n# ------------------------------------------------------------\n\nafficher_texte_capture <- function(titre, nom_objet, texte, n = 1200) {\n  cat('\\n============================================================\\n')\n  cat(titre, '\\n')\n  cat('Objet cr'e'e : ', nom_objet, '\\n', sep = '')\n  cat('============================================================\\n')\n  cat(substr(texte, 1, n))\n\n  if (nchar(texte) > n) {\n    cat('\\n\\n[... texte tronqu'e dans l affichage ...]\\n')\n    cat('Longueur totale : ', nchar(texte), ' caract`eres\\n', sep = '')\n  }\n}\n\nafficher_texte_capture(\n  titre = 'Apercu du texte captur'e pour LinearModel',\n  nom_objet = 'texte_linearmodel',\n  texte = texte_linearmodel\n)\n\nafficher_texte_capture(\n  titre = 'Apercu du texte captur'e pour AovSum',\n  nom_objet = 'texte_aovsum',\n  texte = texte_aovsum\n)\n\n\n# ------------------------------------------------------------\n# 7. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- lm_ftest : F-test de LinearModel\\n')\ncat('- lm_ttest : T-test de LinearModel\\n')\ncat('- lm_resume : r'esum'e du mod`ele lin'eaire\\n')\ncat('- aov_ftest : F-test de AovSum\\n')\ncat('- aov_ttest : T-test de AovSum\\n')\ncat('- texte_linearmodel : sortie compl`ete LinearModel transform'ee en texte\\n')\ncat('- texte_aovsum : sortie compl`ete AovSum transform'ee en texte\\n')",
                                            code_display = "# Inspecter les objets retourn'es par FactoMineR\nnames(res_lm_fm)\nnames(res_aovsum)\n\n# Extraire les sorties importantes de LinearModel()\nlm_ftest <- res_lm_fm$Ftest\nlm_ttest <- res_lm_fm$Ttest\nlm_resume <- res_lm_fm$lmResult\n\n# Extraire les sorties importantes de AovSum()\naov_ftest <- res_aovsum$Ftest\naov_ttest <- res_aovsum$Ttest\n\n# Examiner les objets extraits\nlm_ftest\nlm_ttest\nlm_resume\n\naov_ftest\naov_ttest\n\n# Capturer les sorties compl`etes sous forme de texte\ntexte_linearmodel <- paste(\n  capture.output(print(res_lm_fm)),\n  collapse = '\\n'\n)\n\ntexte_aovsum <- paste(\n  capture.output(print(res_aovsum)),\n  collapse = '\\n'\n)\n\n# V'erifier les textes captur'es\nsubstr(texte_linearmodel, 1, 1200)\nsubstr(texte_aovsum, 1, 1200)\n\nnchar(texte_linearmodel)\nnchar(texte_aovsum)",
                                            expected_output = "Des objets `lm_ftest`, `lm_ttest`, `aov_ftest`, `aov_ttest`, `texte_linearmodel`, `texte_aovsum`, que l'on va pouvoir afficher avec des titres explicites.",
                                            transition = "Ces 'el'ements sont le mat'eriau brut d'un prompt : on sait maintenant extraire, nommer et transformer les sorties statistiques.",
                                            outputs = "console", question = "Quel objet contient la sortie ANOVA cr'e'ee `a la case pr'ec'edente ?",
                                            expected_answer = "res_aovsum", validator = NULL, pdf = NULL,
                                            pdf_on_run = "recuperer.pdf", next_steps = "prompt_manuel",
                                            prerequisites = character(0), concepts = character(0),
                                            layout = list(x = 1040, y = 0)), class = "serious_step"),
         prompt_manuel = structure(list(id = "prompt_manuel", title = "Le Premier Prompt",
                                        section = "r_sorties", objective = "Construire un premier prompt `a la main `a partir des sorties statistiques : assembler manuellement le contexte, les consignes et les r'esultats statistiques pour 'eventuellement interroger une IA.",
                                        text = NULL, code = "# ============================================================\n# Case 6a : construire un prompt manuellement\n# ============================================================\n\n# Objectif de cette case :\n# transformer des sorties statistiques d'ej`a captur'ees\n# en texte organis'e pour un LLM.\n\n# ------------------------------------------------------------\n# 1. Comprendre paste() et cat()\n# ------------------------------------------------------------\n\nobjets_requis <- c('texte_linearmodel', 'texte_aovsum')\n\nobjets_absents <- objets_requis[\n  !vapply(objets_requis, exists, logical(1))\n]\n\nif (length(objets_absents) > 0) {\n  stop(\n    'Objets absents : ',\n    paste(objets_absents, collapse = ', '),\n    '. Ex'ecute d abord la case 5.',\n    call. = FALSE\n  )\n}\n\ncat('\\n============================================================\\n')\ncat('1. Principe : paste() construit une cha^ine de caract`eres\\n')\ncat('============================================================\\n')\n\nexemple_texte <- paste(\n  'Premi`ere ligne',\n  'Deuxi`eme ligne',\n  'Troisi`eme ligne',\n  sep = '\\n'\n)\n\ncat('Objet cr'e'e : exemple_texte\\n')\ncat('Affichage avec cat(exemple_texte) :\\n\\n')\ncat(exemple_texte)\n\ncat('\\n\\n')\ncat('Remarque : paste(..., sep = \"\\\\n\") assemble les lignes.\\n')\ncat('cat() affiche le texte en respectant les retours `a la ligne.\\n')\n\n\n# ------------------------------------------------------------\n# 2. Construire un prompt pour LinearModel()\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('2. Construction du prompt pour LinearModel()\\n')\ncat('============================================================\\n')\n\nprompt_linearmodel <- paste(\n  '# Interpr'etation d une r'egression lin'eaire',\n  '',\n  'Contexte : questionnaire consommateur sur un produit alimentaire.',\n  'Variable `a expliquer : intention_achat.',\n  'Variables explicatives : satisfaction et prix_percu.',\n  '',\n  'Sortie FactoMineR::LinearModel :',\n  texte_linearmodel,\n  '',\n  'Consignes :',\n  '- interpr'eter uniquement les r'esultats fournis ;',\n  '- distinguer effet global et coefficients ;',\n  '- ne pas confondre association et causalit'e ;',\n  '- produire une interpr'etation p'edagogique courte.',\n  sep = '\\n'\n)\n\ncat('Objet cr'e'e : prompt_linearmodel\\n')\ncat('Apercu du prompt :\\n\\n')\ncat(substr(prompt_linearmodel, 1, 1500))\n\nif (nchar(prompt_linearmodel) > 1500) {\n  cat('\\n\\n[... prompt tronqu'e dans l affichage ...]\\n')\n  cat('Longueur totale : ', nchar(prompt_linearmodel), ' caract`eres\\n', sep = '')\n}\n\n\n# ------------------------------------------------------------\n# 3. Construire un prompt pour AovSum()\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('3. Construction du prompt pour AovSum()\\n')\ncat('============================================================\\n')\n\nprompt_aovsum <- paste(\n  '# Interpr'etation d une ANOVA avec interaction',\n  '',\n  'Variable `a expliquer : satisfaction.',\n  'Facteurs : type_produit et budget_contraint.',\n  '',\n  'Sortie FactoMineR::AovSum :',\n  texte_aovsum,\n  '',\n  'Consignes :',\n  '- identifier les effets significatifs ;',\n  '- commenter prudemment l interaction ;',\n  '- ne pas inventer de comparaisons post-hoc.',\n  sep = '\\n'\n)\n\ncat('Objet cr'e'e : prompt_aovsum\\n')\ncat('Apercu du prompt :\\n\\n')\ncat(substr(prompt_aovsum, 1, 1500))\n\nif (nchar(prompt_aovsum) > 1500) {\n  cat('\\n\\n[... prompt tronqu'e dans l affichage ...]\\n')\n  cat('Longueur totale : ', nchar(prompt_aovsum), ' caract`eres\\n', sep = '')\n}\n\n\n# ------------------------------------------------------------\n# 4. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- prompt_linearmodel : prompt construit pour la r'egression lin'eaire\\n')\ncat('- prompt_aovsum : prompt construit pour l ANOVA avec interaction\\n')\ncat('\\n')\ncat('Ces deux objets pourront ^etre envoy'es `a un LLM, ou repris par EnTraineR.\\n')",
                                        code_display = "# Comprendre le principe de paste()\n\nexemple_texte <- paste(\n'Premi`ere ligne',\n'Deuxi`eme ligne',\n'Troisi`eme ligne',\nsep = '\n'\n)\n\nexemple_texte\ncat(exemple_texte)\n\n# Construire un prompt pour LinearModel()\n\nprompt_linearmodel <- paste(\n'# Interpr'etation d une r'egression lin'eaire',\n'',\n'Contexte : questionnaire consommateur sur un produit alimentaire.',\n'Variable `a expliquer : intention_achat.',\n'Variables explicatives : satisfaction et prix_percu.',\n'',\n'Sortie FactoMineR::LinearModel :',\ntexte_linearmodel,\n'',\n'Consignes :',\n'- interpr'eter uniquement les r'esultats fournis ;',\n'- distinguer effet global et coefficients ;',\n'- ne pas confondre association et causalit'e ;',\n'- produire une interpr'etation p'edagogique courte.',\nsep = '\n'\n)\n\n# Examiner le d'ebut du prompt construit\n\nsubstr(prompt_linearmodel, 1, 1500)\nnchar(prompt_linearmodel)\n\n# Construire un prompt pour AovSum()\n\nprompt_aovsum <- paste(\n'# Interpr'etation d une ANOVA avec interaction',\n'',\n'Variable `a expliquer : satisfaction.',\n'Facteurs : type_produit et budget_contraint.',\n'',\n'Sortie FactoMineR::AovSum :',\ntexte_aovsum,\n'',\n'Consignes :',\n'- identifier les effets significatifs ;',\n'- commenter prudemment l interaction ;',\n'- ne pas inventer de comparaisons post-hoc.',\nsep = '\n'\n)\n\n# Examiner le d'ebut du prompt construit\n\nsubstr(prompt_aovsum, 1, 1500)\nnchar(prompt_aovsum)",
                                        expected_output = "Deux prompts : `prompt_linearmodel` et `prompt_aovsum`, construits avec `paste()` puis affich'es avec `cat()`.",
                                        transition = "Ce travail manuel est fastidieux. Nous allons le faire en deux temps : approfondir la construction d un prompt g'en'erique sans coder en dur les noms de variables, puis d'ecouvrir l'outil qui le fera pour nous, EnTraineR.",
                                        outputs = "console", question = "Quelle fonction R permet ici de rassembler des lignes avec des retours `a la ligne ?",
                                        expected_answer = "paste", validator = NULL, pdf = NULL,
                                        pdf_on_run = "prompt_manuel.pdf", next_steps = "prompt_manuel_n2",
                                        prerequisites = character(0), concepts = character(0),
                                        layout = list(x = 1300, y = 0)), class = "serious_step"),
         prompt_manuel_n2 = structure(list(id = "prompt_manuel_n2",
                                           title = "L''Epreuve G'en'erique", section = "r_sorties",
                                           objective = "Rendre la cr'eation de prompts automatique en extrayant automatiquement les noms de variables depuis les formules R.",
                                           text = NULL, code = "# ============================================================\n# Case 6b : prompt manuel niveau 2, sans codage en dur\n# ============================================================\n\n# Dans la case pr'ec'edente, les noms des variables 'etaient 'ecrits `a la main.\n# Ici, on les r'ecup`ere automatiquement `a partir des formules utilis'ees\n# dans les analyses.\n\n# ------------------------------------------------------------\n# 1. Observer les formules utilis'ees\n# ------------------------------------------------------------\n\nobjets_requis <- c(\n  'formule_lm',\n  'formule_aov',\n  'texte_linearmodel',\n  'texte_aovsum'\n)\n\nobjets_absents <- objets_requis[\n  !vapply(objets_requis, exists, logical(1))\n]\n\nif (length(objets_absents) > 0) {\n  stop(\n    'Objets absents : ',\n    paste(objets_absents, collapse = ', '),\n    '. Ex'ecute d abord les cases pr'ec'edentes.',\n    call. = FALSE\n  )\n}\n\ncat('\\n============================================================\\n')\ncat('1. Formules utilis'ees dans les analyses\\n')\ncat('============================================================\\n')\n\ncat('Objet formule_lm :\\n')\nprint(formule_lm)\n\ncat('\\nObjet formule_aov :\\n')\nprint(formule_aov)\n\n\n# ------------------------------------------------------------\n# 2. Comprendre les fonctions utiles\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('2. Extraire les informations d une formule\\n')\ncat('============================================================\\n')\n\ncat('\\nall.vars(formule_lm) renvoie toutes les variables observ'ees :\\n')\nprint(all.vars(formule_lm))\n\ncat('\\nLa premi`ere variable est la variable `a expliquer Y :\\n')\nprint(all.vars(formule_lm)[1])\n\ncat('\\nattr(terms(formule_lm), \"term.labels\") renvoie les termes explicatifs :\\n')\nprint(attr(terms(formule_lm), 'term.labels'))\n\ncat('\\nPour l ANOVA, la distinction est importante :\\n')\ncat('all.vars(formule_aov) donne les variables observ'ees.\\n')\nprint(all.vars(formule_aov))\n\ncat('\\nattr(terms(formule_aov), \"term.labels\") donne les termes du mod`ele, y compris l interaction.\\n')\nprint(attr(terms(formule_aov), 'term.labels'))\n\n\n# ------------------------------------------------------------\n# 3. Cr'eer une fonction pour automatiser cette extraction\n# ------------------------------------------------------------\n\nextraire_infos_formule <- function(formule) {\n\n  variables <- all.vars(formule)\n  termes <- attr(terms(formule), 'term.labels')\n\n  list(\n    formule = deparse(formule),\n    y = variables[1],\n    termes = termes,\n    variables = variables\n  )\n}\n\ninfos_lm <- extraire_infos_formule(formule_lm)\ninfos_aov <- extraire_infos_formule(formule_aov)\n\n\n# ------------------------------------------------------------\n# 4. Afficher les informations extraites\n# ------------------------------------------------------------\n\nafficher_infos_formule <- function(titre, infos) {\n  cat('\\n============================================================\\n')\n  cat(titre, '\\n')\n  cat('============================================================\\n')\n  cat('Formule : ', infos$formule, '\\n', sep = '')\n  cat('Y       : ', infos$y, '\\n', sep = '')\n  cat('Termes  : ', paste(infos$termes, collapse = ', '), '\\n', sep = '')\n  cat('Variables observ'ees : ', paste(infos$variables, collapse = ', '), '\\n', sep = '')\n}\n\nafficher_infos_formule(\n  titre = 'Informations extraites de formule_lm',\n  infos = infos_lm\n)\n\nafficher_infos_formule(\n  titre = 'Informations extraites de formule_aov',\n  infos = infos_aov\n)\n\n\n# ------------------------------------------------------------\n# 5. Construire un prompt g'en'erique pour LinearModel()\n# ------------------------------------------------------------\n\nprompt_linearmodel_n2 <- paste(\n  '# Interpr'etation d une r'egression lin'eaire',\n  '',\n  'Contexte : questionnaire consommateur sur un produit alimentaire.',\n  paste0('Variable `a expliquer : ', infos_lm$y, '.'),\n  paste0('Variables explicatives : ', paste(infos_lm$termes, collapse = ', '), '.'),\n  '',\n  'Sortie FactoMineR::LinearModel :',\n  texte_linearmodel,\n  '',\n  'Consignes :',\n  '- interpr'eter uniquement les r'esultats fournis ;',\n  '- distinguer effet global et coefficients ;',\n  '- ne pas confondre association et causalit'e ;',\n  '- produire une interpr'etation p'edagogique courte.',\n  sep = '\\n'\n)\n\n\n# ------------------------------------------------------------\n# 6. Construire un prompt g'en'erique pour AovSum()\n# ------------------------------------------------------------\n\nprompt_aovsum_n2 <- paste(\n  '# Interpr'etation d une ANOVA',\n  '',\n  paste0('Variable `a expliquer : ', infos_aov$y, '.'),\n  paste0('Termes du mod`ele : ', paste(infos_aov$termes, collapse = ', '), '.'),\n  '',\n  'Sortie FactoMineR::AovSum :',\n  texte_aovsum,\n  '',\n  'Consignes :',\n  '- identifier les effets significatifs ;',\n  '- commenter prudemment les interactions 'eventuelles ;',\n  '- ne pas inventer de comparaisons post-hoc.',\n  sep = '\\n'\n)\n\n\n# ------------------------------------------------------------\n# 7. Afficher un apercu des prompts cr'e'es\n# ------------------------------------------------------------\n\nafficher_apercu_prompt <- function(titre, nom_objet, prompt, n = 1200) {\n  cat('\\n============================================================\\n')\n  cat(titre, '\\n')\n  cat('Objet cr'e'e : ', nom_objet, '\\n', sep = '')\n  cat('============================================================\\n')\n  cat(substr(prompt, 1, n))\n\n  if (nchar(prompt) > n) {\n    cat('\\n\\n[... prompt tronqu'e dans l affichage ...]\\n')\n    cat('Longueur totale : ', nchar(prompt), ' caract`eres\\n', sep = '')\n  }\n}\n\nafficher_apercu_prompt(\n  titre = 'Apercu du prompt g'en'erique LinearModel',\n  nom_objet = 'prompt_linearmodel_n2',\n  prompt = prompt_linearmodel_n2\n)\n\nafficher_apercu_prompt(\n  titre = 'Apercu du prompt g'en'erique AovSum',\n  nom_objet = 'prompt_aovsum_n2',\n  prompt = prompt_aovsum_n2\n)\n\n\n# ------------------------------------------------------------\n# 8. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- infos_lm : informations extraites de formule_lm\\n')\ncat('- infos_aov : informations extraites de formule_aov\\n')\ncat('- prompt_linearmodel_n2 : prompt g'en'erique pour LinearModel\\n')\ncat('- prompt_aovsum_n2 : prompt g'en'erique pour AovSum\\n')\ncat('\\n')\ncat('Id'ee cl'e : le prompt n est plus 'ecrit enti`erement `a la main.\\n')\ncat('Il est construit `a partir des objets R qui d'ecrivent le mod`ele.\\n')",
                                           code_display = "# Observer les formules utilis'ees dans les analyses\n\nformule_lm\nformule_aov\n\n# Extraire les variables observ'ees dans une formule\n\nall.vars(formule_lm)\nall.vars(formule_aov)\n\n# Extraire les termes explicatifs du mod`ele\n\nattr(terms(formule_lm), 'term.labels')\nattr(terms(formule_aov), 'term.labels')\n\n# Cr'eer une fonction pour automatiser l extraction\n\nextraire_infos_formule <- function(formule) {\n\nvariables <- all.vars(formule)\ntermes <- attr(terms(formule), 'term.labels')\n\nlist(\nformule = deparse(formule),\ny = variables[1],\ntermes = termes,\nvariables = variables\n)\n}\n\n# Appliquer la fonction aux deux formules\n\ninfos_lm <- extraire_infos_formule(formule_lm)\ninfos_aov <- extraire_infos_formule(formule_aov)\n\ninfos_lm\ninfos_aov\n\n# Construire un prompt g'en'erique pour LinearModel()\n\nprompt_linearmodel_n2 <- paste(\n'# Interpr'etation d une r'egression lin'eaire',\n'',\n'Contexte : questionnaire consommateur sur un produit alimentaire.',\npaste0('Variable `a expliquer : ', infos_lm$y, '.'),\npaste0('Variables explicatives : ', paste(infos_lm$termes, collapse = ', '), '.'),\n'',\n'Sortie FactoMineR::LinearModel :',\ntexte_linearmodel,\n'',\n'Consignes :',\n'- interpr'eter uniquement les r'esultats fournis ;',\n'- distinguer effet global et coefficients ;',\n'- ne pas confondre association et causalit'e ;',\n'- produire une interpr'etation p'edagogique courte.',\nsep = '\n'\n)\n\n# Construire un prompt g'en'erique pour AovSum()\n\nprompt_aovsum_n2 <- paste(\n'# Interpr'etation d une ANOVA',\n'',\npaste0('Variable `a expliquer : ', infos_aov$y, '.'),\npaste0('Termes du mod`ele : ', paste(infos_aov$termes, collapse = ', '), '.'),\n'',\n'Sortie FactoMineR::AovSum :',\ntexte_aovsum,\n'',\n'Consignes :',\n'- identifier les effets significatifs ;',\n'- commenter prudemment les interactions 'eventuelles ;',\n'- ne pas inventer de comparaisons post-hoc.',\nsep = '\n'\n)\n\n# Examiner les prompts cr'e'es\n\nsubstr(prompt_linearmodel_n2, 1, 1200)\nnchar(prompt_linearmodel_n2)\n\nsubstr(prompt_aovsum_n2, 1, 1200)\nnchar(prompt_aovsum_n2)",
                                           expected_output = "Deux prompts g'en'eriques : `prompt_linearmodel_n2` et `prompt_aovsum_n2`, construits sans coder en dur les noms de Y et des termes explicatifs.",
                                           transition = "Cette 'etape montre la m'ecanique R que EnTraineR va ensuite g'en'eraliser : r'ecup'erer les 'el'ements du mod`ele et produire un prompt.",
                                           outputs = "console", question = "Quel objet contient la formule utilis'ee pour LinearModel ?",
                                           expected_answer = "formule_lm", validator = NULL, pdf = NULL,
                                           pdf_on_run = NULL, next_steps = "entrainer_presentation",
                                           prerequisites = character(0), concepts = character(0),
                                           layout = list(x = 1560, y = 0)), class = "serious_step"),
         entrainer_presentation = structure(list(id = "entrainer_presentation",
                                                 title = "La Forge EnTraineR", section = "entrainer",
                                                 objective = "Comprendre l'int'er^et d'EnTraineR par rapport `a la cr'eation manuelle d'un prompt.",
                                                 text = NULL, code = "# ============================================================\n# Case 7a : La Forge EnTraineR\n# ============================================================\n\n# Objectif de cette case :\n# D'ecouvrir l'existence et la philosophie du package EnTraineR.\n# La th'eorie d'etaill'ee (le sch'ema d'automatisation) sera disponible\n# dans le PDF associ'e apr`es ex'ecution.\n\ncat('\\n============================================================\\n')\ncat('1. Disponibilit'e du package\\n')\ncat('============================================================\\n')\n\nentrainer_disponible <- requireNamespace('EnTraineR', quietly = TRUE)\n\ncat('Package EnTraineR install'e sur cette machine : ', entrainer_disponible, '\\n\\n', sep = '')\n\nif (entrainer_disponible) {\n  fonctions_entrainer <- grep(\n    '^trainer_',\n    getNamespaceExports('EnTraineR'),\n    value = TRUE\n  )\n  cat('Fonctions pr^etes `a l emploi rep'er'ees dans le package :\\n')\n  print(fonctions_entrainer)\n} else {\n  fonctions_entrainer <- c(\n    'trainer_LinearModel',\n    'trainer_linear_model',\n    'trainer_AovSum',\n    'trainer_aovsum',\n    'trainer_cor',\n    'trainer_chisq_test'\n  )\n  cat('Le package n est pas install'e. Voici les fonctions attendues :\\n')\n  print(fonctions_entrainer)\n}\n\ncat('\\n============================================================\\n')\ncat('2. La Philosophie de la Forge\\n')\ncat('============================================================\\n')\ncat('`A letape pr'ec'edente, vous avez 'ecrit beaucoup de code avec paste() et cat()\\n')\ncat('pour transformer une sortie FactoMineR en prompt.\\n\\n')\ncat('EnTraineR a 'et'e concu pour industrialiser cela : il prend directement\\n')\ncat('un objet statistique (comme res_lm_fm) et forge le prompt pour vous.\\n')",
                                                 code_display = "# V'erifier si EnTraineR est disponible sur votre machine\nentrainer_disponible <- requireNamespace('EnTraineR', quietly = TRUE)\n\nentrainer_disponible\n\n# Lister les fonctions d'automatisation disponibles\nif (entrainer_disponible) {\n  fonctions_entrainer <- grep(\n    '^trainer_',\n    getNamespaceExports('EnTraineR'),\n    value = TRUE\n  )\n} else {\n  fonctions_entrainer <- c(\n    'trainer_LinearModel',\n    'trainer_linear_model',\n    'trainer_AovSum',\n    'trainer_aovsum',\n    'trainer_cor',\n    'trainer_chisq_test'\n  )\n}\n\nfonctions_entrainer",
                                                 expected_output = "Une v'erification de l'installation d'EnTraineR et la cr'eation de l'objet `fonctions_entrainer`.",
                                                 transition = "Maintenant que nous connaissons l'outil en th'eorie, utilisons-le concr`etement `a la case suivante.",
                                                 outputs = "console", question = "Quel package transforme automatiquement les sorties FactoMineR en prompts ?",
                                                 expected_answer = "entrainer", validator = NULL, pdf = NULL,
                                                 pdf_on_run = "entrainer_presentation.pdf", next_steps = "entrainer_intro",
                                                 prerequisites = character(0), concepts = character(0),
                                                 layout = list(x = 1560, y = 210)), class = "serious_step"),
         entrainer_intro = structure(list(id = "entrainer_intro",
                                          title = "L''Equipement", section = "entrainer", objective = "Utiliser concr`etement EnTraineR pour g'en'erer un prompt en une seule ligne de code.",
                                          text = NULL, code = "# ============================================================\n# Case 7b : Utilisation pratique d'EnTraineR\n# ============================================================\n\n# Objectif de cette case :\n# Remplacer les dizaines de lignes de notre 'Prompt Manuel'\n# par une seule ligne de code EnTraineR.\n\nif (!exists('res_lm_fm')) {\n  stop(\n    'L objet res_lm_fm est absent. Ex'ecutez d abord la case 3.',\n    call. = FALSE\n  )\n}\n\nprompt_manuel_utilise <- if (exists('prompt_linearmodel_n2')) {\n  prompt_linearmodel_n2\n} else if (exists('prompt_linearmodel')) {\n  prompt_linearmodel\n} else {\n  'Aucun prompt manuel trouv'e'\n}\n\ncat('\\n============================================================\\n')\ncat('1. Le probl`eme : la m'ethode manuelle\\n')\ncat('============================================================\\n')\ncat('Pour cr'eer l objet prompt_linearmodel, il fallait extraire le F-test,\\n')\ncat('le T-test, formater les r'esultats en texte, et dicter les consignes.\\n')\n\ncat('\\n============================================================\\n')\ncat('2. La solution : ex'ecution robuste\\n')\ncat('============================================================\\n')\n\nentrainer_disponible <- requireNamespace('EnTraineR', quietly = TRUE)\n\nif (entrainer_disponible) {\n\n  fonctions_entrainer <- getNamespaceExports('EnTraineR')\n  nom_trainer_lm <- intersect(\n    c('trainer_LinearModel', 'trainer_linear_model'),\n    fonctions_entrainer\n  )[1]\n\n  if (is.na(nom_trainer_lm)) {\n    stop(\n      'Aucune fonction trainer_LinearModel ou trainer_linear_model n a 'et'e trouv'ee dans EnTraineR.',\n      call. = FALSE\n    )\n  }\n\n  trainer_lm <- getExportedValue('EnTraineR', nom_trainer_lm)\n\n  prompt_auto_lm <- tryCatch(\n    trainer_lm(res_lm_fm, generate = FALSE),\n    error = function(e) paste('Erreur :', conditionMessage(e))\n  )\n\n  texte_prompt_auto_lm <- if(is.list(prompt_auto_lm) && 'prompt' %in% names(prompt_auto_lm)) {\n     prompt_auto_lm$prompt\n  } else {\n     as.character(prompt_auto_lm)\n  }\n  texte_prompt_auto_lm <- gsub('\\\\n', '\\n', texte_prompt_auto_lm)\n\n  cat('Objet cr'e'e : prompt_auto_lm\\n\\n')\n\n  cat('--- Comparaison avec l ancienne m'ethode ---\\n')\n  comparaison_prompt_manuel_auto <- data.frame(\n    methode = c('Prompt manuel', 'Prompt EnTraineR'),\n    objet = c('prompt_linearmodel', 'prompt_auto_lm'),\n    logique = c(\n      'capture.output() + paste() + consignes 'ecrites `a la main',\n      'appel direct `a une fonction trainer_*'\n    ),\n    caracteres = c(nchar(prompt_manuel_utilise), nchar(texte_prompt_auto_lm)),\n    stringsAsFactors = FALSE\n  )\n  print(comparaison_prompt_manuel_auto, row.names = FALSE)\n\n  cat('\\nApercu du prompt g'en'er'e magiquement par le package :\\n\\n')\n  cat(substr(texte_prompt_auto_lm, 1, 1000))\n  if(nchar(texte_prompt_auto_lm) > 1000) cat('\\n\\n[... suite du prompt tronqu'ee ...]\\n')\n\n} else {\n\n  cat('Le package EnTraineR n\\'est pas install'e.\\n')\n  cat('Si cetait le cas, voici le code robuste que nous aurions ex'ecut'e :\\n\\n')\n  cat('trainer_lm <- getExportedValue(\"EnTraineR\", nom_trainer_lm)\\n')\n  cat('prompt_auto_lm <- trainer_lm(\\n')\n  cat('  res_lm_fm, \\n')\n  cat('  generate = FALSE\\n')\n  cat(')\\n\\n')\n  cat('En une seule ligne, la fonction extrait les donn'ees de res_lm_fm\\n')\n  cat('et produit un prompt similaire `a notre ancien prompt_linearmodel.\\n')\n}",
                                          code_display = "# Rappel : res_lm_fm contient notre r'egression construite `a la case 3.\n\nif (!exists('res_lm_fm')) {\n  stop(\n    'L objet res_lm_fm est absent. Ex'ecutez d abord la case 3.',\n    call. = FALSE\n  )\n}\n\n# Au lieu de construire le prompt avec paste(),\n# on laisse EnTraineR produire le prompt automatiquement.\n\nif (requireNamespace('EnTraineR', quietly = TRUE)) {\n\n  fonctions_entrainer <- getNamespaceExports('EnTraineR')\n\n  nom_trainer_lm <- intersect(\n    c('trainer_LinearModel', 'trainer_linear_model'),\n    fonctions_entrainer\n  )[1]\n\n  trainer_lm <- getExportedValue(\n    'EnTraineR',\n    nom_trainer_lm\n  )\n\n  prompt_auto_lm <- trainer_lm(\n    res_lm_fm,\n    generate = FALSE\n  )\n\n  prompt_auto_lm\n\n} else {\n  message('Installez le package EnTraineR pour tester cette commande.')\n}",
                                          expected_output = "Un prompt g'en'er'e automatiquement (`prompt_auto_lm`) et une comparaison avec la m'ethode manuelle.",
                                          transition = "Nous savons automatiser la cr'eation d'un prompt. Comment automatiser l'analyse de plusieurs variables d'un coup ?",
                                          outputs = "console", question = "Quelle option cruciale d'EnTraineR permet de v'erifier le prompt sans appeler l'IA ?",
                                          expected_answer = "generate = FALSE", validator = NULL,
                                          pdf = NULL, pdf_on_run = "entrainer_exemple.pdf", next_steps = "boucle_y_x",
                                          prerequisites = character(0), concepts = character(0),
                                          layout = list(x = 1300, y = 210)), class = "serious_step"),
         boucle_y_x = structure(list(id = "boucle_y_x", title = "La Boucle d'Automatisation",
                                     section = "r_sorties", objective = "Passer de Y~X `a Y~tous les X pour comprendre la logique d'automatisation.",
                                     text = NULL, code = "# ============================================================\n# Case 8 : boucler sur plusieurs variables explicatives\n# ============================================================\n\n# Objectif de cette case :\n# comprendre comment passer d une analyse unique :\n# intention_achat ~ prix_percu\n# `a une s'erie d analyses :\n# intention_achat ~ prix_percu\n# intention_achat ~ plaisir\n# intention_achat ~ naturalite\n# etc.\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop('Installe FactoMineR : install.packages(\"FactoMineR\")')\n}\n\n\n# ------------------------------------------------------------\n# 1. D'efinir la variable Y et les variables X\n# ------------------------------------------------------------\n\ny <- 'intention_achat'\n\nvariables_x <- c(\n  'prix_percu',\n  'plaisir',\n  'naturalite',\n  'confiance',\n  'ancrage_local',\n  'usage_numerique',\n  'sensibilite_env'\n)\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord Le Grand D'epart.',\n    call. = FALSE\n  )\n}\n\nvariables_requises <- c(y, variables_x)\n\nvariables_absentes <- setdiff(\n  variables_requises,\n  names(questionnaire)\n)\n\nif (length(variables_absentes) > 0) {\n  stop(\n    'Variables absentes du questionnaire : ',\n    paste(variables_absentes, collapse = ', '),\n    call. = FALSE\n  )\n}\n\ncat('\\n============================================================\\n')\ncat('1. Variables utilis'ees pour la boucle\\n')\ncat('============================================================\\n')\ncat('Variable `a expliquer Y : ', y, '\\n', sep = '')\ncat('Variables explicatives X :\\n')\nprint(variables_x)\n\n\n# ------------------------------------------------------------\n# 2. Comprendre la construction d une formule\n# ------------------------------------------------------------\n\n# Pour automatiser une analyse, on construit d abord la formule\n# sous forme de texte, puis on la transforme en formule R.\n\npremier_x <- variables_x[1]\n\nformule_texte <- paste(y, '~', premier_x)\nformule_exemple <- as.formula(formule_texte)\n\ncat('\\n============================================================\\n')\ncat('2. Construire une formule automatiquement\\n')\ncat('============================================================\\n')\ncat('Premier X utilis'e comme exemple : ', premier_x, '\\n', sep = '')\ncat('Formule sous forme de texte : ', formule_texte, '\\n', sep = '')\ncat('Formule transform'ee en objet R avec as.formula() :\\n')\nprint(formule_exemple)\n\n\n# ------------------------------------------------------------\n# 3. Ajuster un premier mod`ele sans boucle\n# ------------------------------------------------------------\n\nmodele_exemple <- FactoMineR::LinearModel(\n  formule_exemple,\n  data = questionnaire,\n  selection = 'none'\n)\n\ncat('\\n============================================================\\n')\ncat('3. Premier mod`ele ajust'e sans boucle\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : modele_exemple\\n')\ncat('Mod`ele ajust'e : ', formule_texte, '\\n', sep = '')\n\ncat('\\nFtest du mod`ele exemple :\\n')\nprint(modele_exemple$Ftest)\n\ncat('\\nTtest du mod`ele exemple :\\n')\nprint(modele_exemple$Ttest)\n\n\n# ------------------------------------------------------------\n# 4. 'Ecrire une fonction pour r'ep'eter l analyse\n# ------------------------------------------------------------\n\n# Quand une suite d instructions doit ^etre r'ep'et'ee,\n# on peut l enfermer dans une fonction.\n\najuster_un_modele <- function(x) {\n\n  formule_texte <- paste(y, '~', x)\n  formule <- as.formula(formule_texte)\n\n  modele <- FactoMineR::LinearModel(\n    formule,\n    data = questionnaire,\n    selection = 'none'\n  )\n\n  modele\n}\n\ncat('\\n============================================================\\n')\ncat('4. Fonction cr'e'ee pour automatiser une analyse\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : ajuster_un_modele()\\n')\ncat('R^ole : recevoir le nom d une variable X et retourner un mod`ele LinearModel.\\n')\n\n\n# ------------------------------------------------------------\n# 5. Appliquer la fonction `a toutes les variables X\n# ------------------------------------------------------------\n\n# lapply() applique une m^eme fonction `a chaque 'el'ement d un vecteur.\n# Ici, chaque 'el'ement de variables_x est un nom de variable explicative.\n\nmodeles_univaries <- lapply(\n  variables_x,\n  ajuster_un_modele\n)\n\nnames(modeles_univaries) <- variables_x\n\ncat('\\n============================================================\\n')\ncat('5. Boucle avec lapply()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : modeles_univaries\\n')\ncat('Nombre de mod`eles ajust'es : ', length(modeles_univaries), '\\n', sep = '')\ncat('Noms des mod`eles dans la liste :\\n')\nprint(names(modeles_univaries))\n\n\n# ------------------------------------------------------------\n# 6. Afficher un r'esum'e lisible des mod`eles obtenus\n# ------------------------------------------------------------\n\nafficher_modele_univarie <- function(nom_x, modele) {\n  cat('\\n============================================================\\n')\n  cat('Mod`ele univari'e : ', y, ' ~ ', nom_x, '\\n', sep = '')\n  cat('Objet dans la liste : modeles_univaries[[\"', nom_x, '\"]]\\n', sep = '')\n  cat('============================================================\\n')\n\n  cat('\\nFtest :\\n')\n  print(modele$Ftest)\n\n  cat('\\nTtest :\\n')\n  print(modele$Ttest)\n}\n\n# On affiche seulement les deux premiers mod`eles pour ne pas saturer la console.\nafficher_modele_univarie(\n  nom_x = names(modeles_univaries)[1],\n  modele = modeles_univaries[[1]]\n)\n\nafficher_modele_univarie(\n  nom_x = names(modeles_univaries)[2],\n  modele = modeles_univaries[[2]]\n)\n\ncat('\\n[Seuls les deux premiers mod`eles sont affich'es. Les autres sont bien stock'es dans modeles_univaries.]\\n')\n\n\n# ------------------------------------------------------------\n# 7. Capturer les sorties sous forme de texte\n# ------------------------------------------------------------\n\ntextes_modeles_univaries <- lapply(\n  modeles_univaries,\n  function(modele) {\n    paste(\n      capture.output(print(modele)),\n      collapse = '\\n'\n    )\n  }\n)\n\ncat('\\n============================================================\\n')\ncat('7. Sorties captur'ees sous forme de texte\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : textes_modeles_univaries\\n')\ncat('Chaque 'el'ement contient la sortie compl`ete d un mod`ele sous forme de texte.\\n')\ncat('Noms des textes captur'es :\\n')\nprint(names(textes_modeles_univaries))\n\n\n# ------------------------------------------------------------\n# 8. Afficher un apercu d une sortie captur'ee\n# ------------------------------------------------------------\n\npremier_texte <- textes_modeles_univaries[[1]]\n\ncat('\\n============================================================\\n')\ncat('8. Apercu du premier texte captur'e\\n')\ncat('============================================================\\n')\ncat('Objet affich'e : textes_modeles_univaries[[1]]\\n')\ncat('Variable X correspondante : ', names(textes_modeles_univaries)[1], '\\n\\n', sep = '')\n\ncat(substr(premier_texte, 1, 1200))\n\nif (nchar(premier_texte) > 1200) {\n  cat('\\n\\n[... texte tronqu'e dans l affichage ...]\\n')\n  cat('Longueur totale : ', nchar(premier_texte), ' caract`eres\\n', sep = '')\n}\n\n\n# ------------------------------------------------------------\n# 9. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- y : nom de la variable `a expliquer\\n')\ncat('- variables_x : noms des variables explicatives test'ees\\n')\ncat('- formule_exemple : premi`ere formule construite automatiquement\\n')\ncat('- modele_exemple : premier mod`ele ajust'e sans boucle\\n')\ncat('- ajuster_un_modele() : fonction qui ajuste un mod`ele pour une variable X\\n')\ncat('- modeles_univaries : liste des mod`eles LinearModel\\n')\ncat('- textes_modeles_univaries : liste des sorties transform'ees en texte\\n')\ncat('\\n')\ncat('Id'ee cl'e : on vient d automatiser une s'erie de mod`eles simples.\\n')\ncat('La case suivante montrera que condes() g'en'eralise cette logique.\\n')",
                                     code_display = "# V'erifier que FactoMineR est disponible\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\nstop(\n  'Installe FactoMineR avec install.packages(\"FactoMineR\")',\n  call. = FALSE\n)\n}\n\n# D'efinir la variable `a expliquer\n\ny <- 'intention_achat'\n\n# D'efinir les variables explicatives `a tester\n\nvariables_x <- c(\n'prix_percu',\n'plaisir',\n'naturalite',\n'confiance',\n'ancrage_local',\n'usage_numerique',\n'sensibilite_env'\n)\n\ny\nvariables_x\n\n# Construire une premi`ere formule automatiquement\n\npremier_x <- variables_x[1]\n\nformule_texte <- paste(y, '~', premier_x)\nformule_exemple <- as.formula(formule_texte)\n\nformule_texte\nformule_exemple\n\n# Ajuster un premier mod`ele sans boucle\n\nmodele_exemple <- FactoMineR::LinearModel(\nformule_exemple,\ndata = questionnaire,\nselection = 'none'\n)\n\nmodele_exemple$Ftest\nmodele_exemple$Ttest\n\n# 'Ecrire une fonction qui ajuste un mod`ele pour une variable X\n\najuster_un_modele <- function(x) {\n\nformule_texte <- paste(y, '~', x)\nformule <- as.formula(formule_texte)\n\nmodele <- FactoMineR::LinearModel(\nformule,\ndata = questionnaire,\nselection = 'none'\n)\n\nmodele\n}\n\n# Appliquer la fonction `a toutes les variables X\n\nmodeles_univaries <- lapply(\nvariables_x,\najuster_un_modele\n)\n\nnames(modeles_univaries) <- variables_x\n\nlength(modeles_univaries)\nnames(modeles_univaries)\n\n# Examiner les deux premiers mod`eles obtenus\n\nmodeles_univaries[[1]]$Ftest\nmodeles_univaries[[1]]$Ttest\n\nmodeles_univaries[[2]]$Ftest\nmodeles_univaries[[2]]$Ttest\n\n# Capturer les sorties compl`etes sous forme de texte\n\ntextes_modeles_univaries <- lapply(\nmodeles_univaries,\nfunction(modele) {\npaste(\ncapture.output(print(modele)),\ncollapse = '\n'\n)\n}\n)\n\nnames(textes_modeles_univaries)\n\n# Examiner un premier texte captur'e\n\npremier_texte <- textes_modeles_univaries[[1]]\n\nsubstr(premier_texte, 1, 1200)\nnchar(premier_texte)",
                                     expected_output = "Une liste de mod`eles `modeles_univaries` et une liste de sorties textuelles `textes_modeles_univaries`, une par variable explicative.",
                                     transition = "On vient de faire `a la main ce que condes() g'en'eralise pour d'ecrire une variable quantitative.",
                                     outputs = "console", question = "Quelle fonction R applique une m^eme fonction `a tous les 'el'ements d une liste ou d un vecteur ?",
                                     expected_answer = "lapply", validator = NULL, pdf = NULL,
                                     pdf_on_run = "boucle_y_x.pdf", next_steps = "condes",
                                     prerequisites = character(0), concepts = character(0),
                                     layout = list(x = 1040, y = 210)), class = "serious_step"),
         condes = structure(list(id = "condes", title = "Le Versant Continu",
                                 section = "stat", objective = "Utiliser condes() pour d'ecrire une variable quantitative par toutes les autres.",
                                 text = NULL, code = "# ============================================================\n# Case 9 : condes()\n# ============================================================\n\n# Objectif de cette case :\n# comprendre que condes() d'ecrit une variable quantitative\n# `a partir de toutes les autres variables du tableau.\n#\n# Pour une variable quantitative `a d'ecrire :\n# - les variables quantitatives sont li'ees par corr'elation ;\n# - les variables qualitatives sont li'ees par comparaison de moyennes.\n#\n# On retrouve donc la logique des analyses simples vues avant,\n# mais appliqu'ee syst'ematiquement.\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop('Installe FactoMineR : install.packages(\"FactoMineR\")')\n}\n\n\n# ------------------------------------------------------------\n# 1. Pr'eparer le tableau de description\n# ------------------------------------------------------------\n\n# On retire la variable textuelle libre.\n# condes() et catdes() travaillent ici sur des variables quantitatives\n# et qualitatives structur'ees, pas directement sur les verbatims.\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord Le Grand D'epart.',\n    call. = FALSE\n  )\n}\n\nquestionnaire_desc <- questionnaire[\n  ,\n  setdiff(names(questionnaire), 'commentaire')\n]\n\ny_condes <- 'intention_achat'\n\nif (!y_condes %in% names(questionnaire_desc)) {\n  stop(\n    'La variable intention_achat est absente de questionnaire_desc.',\n    call. = FALSE\n  )\n}\n\nnum_var_condes <- which(names(questionnaire_desc) == y_condes)\n\ncat('\\n============================================================\\n')\ncat('1. Variable quantitative `a d'ecrire\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : questionnaire_desc\\n')\ncat('Variable d'ecrite : ', y_condes, '\\n', sep = '')\ncat('Position de cette variable dans questionnaire_desc : ', num_var_condes, '\\n', sep = '')\n\n\n# ------------------------------------------------------------\n# 2. Retrouver manuellement la logique c^ot'e variables quantitatives\n# ------------------------------------------------------------\n\nvariables_quanti_condes <- setdiff(\n  names(questionnaire_desc)[vapply(questionnaire_desc, is.numeric, logical(1))],\n  c('id', y_condes)\n)\n\ncorrelations_y <- data.frame(\n  variable = variables_quanti_condes,\n  correlation = vapply(\n    variables_quanti_condes,\n    function(v) {\n      cor(\n        questionnaire_desc[[y_condes]],\n        questionnaire_desc[[v]],\n        use = 'pairwise.complete.obs'\n      )\n    },\n    numeric(1)\n  ),\n  row.names = NULL\n)\n\ncorrelations_y$abs_correlation <- abs(correlations_y$correlation)\n\ncorrelations_y <- correlations_y[\n  order(correlations_y$abs_correlation, decreasing = TRUE),\n]\n\ncorrelations_y$correlation <- round(correlations_y$correlation, 3)\ncorrelations_y$abs_correlation <- round(correlations_y$abs_correlation, 3)\n\ncat('\\n============================================================\\n')\ncat('2. Logique statistique : liens avec les variables quantitatives\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : correlations_y\\n')\ncat('Lecture : plus la corr'elation est forte en valeur absolue,\\n')\ncat('plus la variable est associ'ee `a ', y_condes, '.\\n', sep = '')\nprint(correlations_y, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 3. Retrouver manuellement la logique c^ot'e variables qualitatives\n# ------------------------------------------------------------\n\nvariables_quali_condes <- names(questionnaire_desc)[\n  vapply(questionnaire_desc, is.factor, logical(1))\n]\n\ncalcul_eta2 <- function(variable_quali) {\n  formule <- as.formula(paste(y_condes, '~', variable_quali))\n  tab <- summary(aov(formule, data = questionnaire_desc))[[1]]\n\n  ss <- tab[['Sum Sq']]\n  eta2 <- ss[1] / sum(ss)\n\n  data.frame(\n    variable = variable_quali,\n    eta2 = eta2,\n    p_value = tab[['Pr(>F)']][1],\n    row.names = NULL\n  )\n}\n\nliaisons_quali_y <- do.call(\n  rbind,\n  lapply(variables_quali_condes, calcul_eta2)\n)\n\nliaisons_quali_y <- liaisons_quali_y[\n  order(liaisons_quali_y$eta2, decreasing = TRUE),\n]\n\nliaisons_quali_y$eta2 <- round(liaisons_quali_y$eta2, 3)\nliaisons_quali_y$p_value <- signif(liaisons_quali_y$p_value, 3)\n\ncat('\\n============================================================\\n')\ncat('3. Logique statistique : liens avec les variables qualitatives\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : liaisons_quali_y\\n')\ncat('Lecture : eta2 mesure la part de variabilit'e de ', y_condes, '\\n', sep = '')\ncat('associ'ee `a chaque variable qualitative.\\n')\nprint(liaisons_quali_y, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 4. Utiliser condes()\n# ------------------------------------------------------------\n\nres_condes <- FactoMineR::condes(\n  questionnaire_desc,\n  num.var = num_var_condes\n)\n\ncat('\\n============================================================\\n')\ncat('4. R'esultat FactoMineR::condes()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_condes\\n')\ncat('condes() automatise la description de la variable quantitative.\\n')\ncat('Variable d'ecrite : ', y_condes, '\\n', sep = '')\n\ncat('\\n'El'ements contenus dans res_condes :\\n')\nprint(names(res_condes))\n\n\n# ------------------------------------------------------------\n# 5. Afficher la sortie avec un titre explicite\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('5. Sortie compl`ete de condes()\\n')\ncat('============================================================\\n')\nprint(res_condes)\n\n\n# ------------------------------------------------------------\n# 6. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- questionnaire_desc : tableau sans la variable textuelle libre\\n')\ncat('- y_condes : nom de la variable quantitative d'ecrite\\n')\ncat('- num_var_condes : position de cette variable dans questionnaire_desc\\n')\ncat('- correlations_y : liens avec les variables quantitatives\\n')\ncat('- liaisons_quali_y : liens avec les variables qualitatives\\n')\ncat('- res_condes : r'esultat complet de FactoMineR::condes()\\n')\ncat('\\n')\ncat('Id'ee cl'e : condes() g'en'eralise des analyses simples pour d'ecrire une variable quantitative.\\n')",
                                 code_display = "# V'erifier que FactoMineR est disponible\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\nstop(\n  'Installe FactoMineR avec install.packages(\"FactoMineR\")',\n  call. = FALSE\n)\n}\n\n# Pr'eparer le tableau de description\n\n# On retire la variable textuelle libre.\n\nquestionnaire_desc <- questionnaire[\n,\nsetdiff(names(questionnaire), 'commentaire')\n]\n\n# D'efinir la variable quantitative `a d'ecrire\n\ny_condes <- 'intention_achat'\n\nnum_var_condes <- which(\nnames(questionnaire_desc) == y_condes\n)\n\nquestionnaire_desc\ny_condes\nnum_var_condes\n\n# Retrouver manuellement la logique c^ot'e variables quantitatives\n\nvariables_quanti_condes <- setdiff(\nnames(questionnaire_desc)[vapply(questionnaire_desc, is.numeric, logical(1))],\nc('id', y_condes)\n)\n\ncorrelations_y <- data.frame(\nvariable = variables_quanti_condes,\ncorrelation = vapply(\nvariables_quanti_condes,\nfunction(v) {\ncor(\nquestionnaire_desc[[y_condes]],\nquestionnaire_desc[[v]],\nuse = 'pairwise.complete.obs'\n)\n},\nnumeric(1)\n),\nrow.names = NULL\n)\n\ncorrelations_y$abs_correlation <- abs(\ncorrelations_y$correlation\n)\n\ncorrelations_y <- correlations_y[\norder(correlations_y$abs_correlation, decreasing = TRUE),\n]\n\ncorrelations_y$correlation <- round(\ncorrelations_y$correlation,\n3\n)\n\ncorrelations_y$abs_correlation <- round(\ncorrelations_y$abs_correlation,\n3\n)\n\ncorrelations_y\n\n# Retrouver manuellement la logique c^ot'e variables qualitatives\n\nvariables_quali_condes <- names(questionnaire_desc)[\nvapply(questionnaire_desc, is.factor, logical(1))\n]\n\ncalcul_eta2 <- function(variable_quali) {\n\nformule <- as.formula(\npaste(y_condes, '~', variable_quali)\n)\n\ntab <- summary(\naov(formule, data = questionnaire_desc)\n)[[1]]\n\nss <- tab[['Sum Sq']]\neta2 <- ss[1] / sum(ss)\n\ndata.frame(\nvariable = variable_quali,\neta2 = eta2,\np_value = tab[['Pr(>F)']][1],\nrow.names = NULL\n)\n}\n\nliaisons_quali_y <- do.call(\nrbind,\nlapply(variables_quali_condes, calcul_eta2)\n)\n\nliaisons_quali_y <- liaisons_quali_y[\norder(liaisons_quali_y$eta2, decreasing = TRUE),\n]\n\nliaisons_quali_y$eta2 <- round(\nliaisons_quali_y$eta2,\n3\n)\n\nliaisons_quali_y$p_value <- signif(\nliaisons_quali_y$p_value,\n3\n)\n\nliaisons_quali_y\n\n# Utiliser FactoMineR::condes()\n\nres_condes <- FactoMineR::condes(\nquestionnaire_desc,\nnum.var = num_var_condes\n)\n\n# Examiner le contenu de l objet retourn'e\n\nnames(res_condes)\n\n# Afficher le r'esultat complet\n\nres_condes",
                                 expected_output = "Une description de `intention_achat` par les variables quantitatives et qualitatives, avec un rappel de la logique statistique sous-jacente.",
                                 transition = "On passe maintenant `a la description d'une variable qualitative avec catdes().",
                                 outputs = "console", question = "Quelle fonction FactoMineR d'ecrit une variable quantitative continue ?",
                                 expected_answer = "condes", validator = NULL, pdf = NULL,
                                 pdf_on_run = NULL, next_steps = "catdes", prerequisites = character(0),
                                 concepts = character(0), layout = list(x = 780, y = 210)), class = "serious_step"),
         catdes = structure(list(id = "catdes", title = "Le Versant Cat'egoriel",
                                 section = "stat", objective = "Utiliser catdes() pour d'ecrire une variable qualitative ou des groupes.",
                                 text = NULL, code = "# ============================================================\n# Case 10 : catdes()\n# ============================================================\n\n# Objectif de cette case :\n# comprendre que catdes() d'ecrit une variable qualitative,\n# c est-`a-dire des modalit'es ou des groupes.\n#\n# Pour une variable qualitative `a d'ecrire :\n# - les variables quantitatives sont compar'ees entre les groupes ;\n# - les variables qualitatives sont crois'ees avec les groupes.\n#\n# On retrouve donc la logique de l ANOVA et du khi-deux,\n# mais appliqu'ee syst'ematiquement.\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop('Installe FactoMineR : install.packages(\"FactoMineR\")')\n}\n\n\nif (!exists('questionnaire_desc')) {\n  if (!exists('questionnaire')) {\n    stop(\n      'Les objets questionnaire_desc et questionnaire sont absents. Ex'ecute d abord les cases pr'ec'edentes.',\n      call. = FALSE\n    )\n  }\n\n  questionnaire_desc <- questionnaire[\n    ,\n    setdiff(names(questionnaire), 'commentaire')\n  ]\n}\n\n# ------------------------------------------------------------\n# 1. Identifier la variable qualitative `a d'ecrire\n# ------------------------------------------------------------\n\ny_catdes <- 'profil_alim'\n\nif (!y_catdes %in% names(questionnaire_desc)) {\n  stop(\n    'La variable profil_alim est absente de questionnaire_desc.',\n    call. = FALSE\n  )\n}\n\nnum_var_catdes <- which(names(questionnaire_desc) == y_catdes)\n\ncat('\\n============================================================\\n')\ncat('1. Variable qualitative `a d'ecrire\\n')\ncat('============================================================\\n')\ncat('Variable d'ecrite : ', y_catdes, '\\n', sep = '')\ncat('Position de cette variable dans questionnaire_desc : ', num_var_catdes, '\\n', sep = '')\n\ncat('\\nR'epartition des groupes :\\n')\nprint(table(questionnaire_desc[[y_catdes]]))\n\n\n# ------------------------------------------------------------\n# 2. Logique statistique avec les variables quantitatives\n# ------------------------------------------------------------\n\n# Exemple : comparer quelques moyennes selon le profil alimentaire.\n\nvariables_quanti_exemple <- c(\n  'satisfaction',\n  'intention_achat',\n  'prix_percu',\n  'naturalite',\n  'ancrage_local'\n)\n\nmoyennes_par_profil <- aggregate(\n  questionnaire_desc[variables_quanti_exemple],\n  by = list(profil = questionnaire_desc[[y_catdes]]),\n  FUN = mean\n)\n\nmoyennes_par_profil[, -1] <- round(moyennes_par_profil[, -1], 2)\n\ncat('\\n============================================================\\n')\ncat('2. Logique statistique : moyennes par profil\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : moyennes_par_profil\\n')\ncat('Lecture : on compare les moyennes des variables quantitatives\\n')\ncat('entre les modalit'es de ', y_catdes, '.\\n', sep = '')\nprint(moyennes_par_profil, row.names = FALSE)\n\n\n# Exemple d ANOVA simple pour une variable quantitative.\nanova_satisfaction_profil <- aov(\n  satisfaction ~ profil_alim,\n  data = questionnaire_desc\n)\n\ncat('\\n============================================================\\n')\ncat('3. Exemple : ANOVA satisfaction ~ profil_alim\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : anova_satisfaction_profil\\n')\nprint(summary(anova_satisfaction_profil))\n\n\n# ------------------------------------------------------------\n# 3. Logique statistique avec les variables qualitatives\n# ------------------------------------------------------------\n\n# Exemple : croiser profil_alim avec type_produit.\n\ntable_profil_produit <- table(\n  questionnaire_desc[[y_catdes]],\n  questionnaire_desc$type_produit\n)\n\ntest_chi2_profil_produit <- chisq.test(table_profil_produit)\n\ncat('\\n============================================================\\n')\ncat('4. Exemple : tableau crois'e profil_alim x type_produit\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : table_profil_produit\\n')\nprint(table_profil_produit)\n\ncat('\\nTest du khi-deux associ'e :\\n')\ncat('Objet cr'e'e : test_chi2_profil_produit\\n')\nprint(test_chi2_profil_produit)\n\n\n# ------------------------------------------------------------\n# 4. Utiliser catdes()\n# ------------------------------------------------------------\n\nres_catdes <- FactoMineR::catdes(\n  questionnaire_desc,\n  num.var = num_var_catdes\n)\n\ncat('\\n============================================================\\n')\ncat('5. R'esultat FactoMineR::catdes()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_catdes\\n')\ncat('catdes() automatise la description des groupes ou modalit'es.\\n')\ncat('Variable d'ecrite : ', y_catdes, '\\n', sep = '')\n\ncat('\\n'El'ements contenus dans res_catdes :\\n')\nprint(names(res_catdes))\n\n\n# ------------------------------------------------------------\n# 5. Afficher la sortie avec un titre explicite\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('6. Sortie compl`ete de catdes()\\n')\ncat('============================================================\\n')\nprint(res_catdes)\n\n\n# ------------------------------------------------------------\n# 6. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- y_catdes : nom de la variable qualitative d'ecrite\\n')\ncat('- num_var_catdes : position de cette variable dans questionnaire_desc\\n')\ncat('- moyennes_par_profil : comparaison de moyennes par profil\\n')\ncat('- anova_satisfaction_profil : exemple d ANOVA simple par profil\\n')\ncat('- table_profil_produit : tableau crois'e profil x produit\\n')\ncat('- test_chi2_profil_produit : test du khi-deux associ'e\\n')\ncat('- res_catdes : r'esultat complet de FactoMineR::catdes()\\n')\ncat('\\n')\ncat('Id'ee cl'e : catdes() g'en'eralise des ANOVA et tableaux crois'es pour d'ecrire des groupes.\\n')",
                                 code_display = "# V'erifier que FactoMineR est disponible\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\nstop(\n  'Installe FactoMineR avec install.packages(\"FactoMineR\")',\n  call. = FALSE\n)\n}\n\n# Identifier la variable qualitative `a d'ecrire\n\ny_catdes <- 'profil_alim'\n\nnum_var_catdes <- which(\nnames(questionnaire_desc) == y_catdes\n)\n\ny_catdes\nnum_var_catdes\n\n# Examiner la r'epartition des groupes\n\ntable(questionnaire_desc[[y_catdes]])\n\n# Comparer quelques moyennes selon le profil alimentaire\n\nvariables_quanti_exemple <- c(\n'satisfaction',\n'intention_achat',\n'prix_percu',\n'naturalite',\n'ancrage_local'\n)\n\nmoyennes_par_profil <- aggregate(\nquestionnaire_desc[variables_quanti_exemple],\nby = list(profil = questionnaire_desc[[y_catdes]]),\nFUN = mean\n)\n\nmoyennes_par_profil[, -1] <- round(\nmoyennes_par_profil[, -1],\n2\n)\n\nmoyennes_par_profil\n\n# Exemple d ANOVA simple pour une variable quantitative\n\nanova_satisfaction_profil <- aov(\nsatisfaction ~ profil_alim,\ndata = questionnaire_desc\n)\n\nsummary(anova_satisfaction_profil)\n\n# Exemple de croisement entre deux variables qualitatives\n\ntable_profil_produit <- table(\nquestionnaire_desc[[y_catdes]],\nquestionnaire_desc$type_produit\n)\n\ntable_profil_produit\n\n# Test du khi-deux associ'e au tableau crois'e\n\ntest_chi2_profil_produit <- chisq.test(\ntable_profil_produit\n)\n\ntest_chi2_profil_produit\n\n# Utiliser FactoMineR::catdes()\n\nres_catdes <- FactoMineR::catdes(\nquestionnaire_desc,\nnum.var = num_var_catdes\n)\n\n# Examiner le contenu de l objet retourn'e\n\nnames(res_catdes)\n\n# Afficher le r'esultat complet\n\nres_catdes",
                                 expected_output = "Une description des profils alimentaires par variables quantitatives et qualitatives, avec un rappel de la logique statistique sous-jacente.",
                                 transition = "Les sorties condes/catdes sont plus riches : il faut apprendre `a les manipuler.",
                                 outputs = "console", question = "Quelle fonction FactoMineR d'ecrit une variable qualitative ou des groupes ?",
                                 expected_answer = "catdes", validator = NULL, pdf = NULL,
                                 pdf_on_run = NULL, next_steps = "manip_condes_catdes",
                                 prerequisites = character(0), concepts = character(0),
                                 layout = list(x = 520, y = 210)), class = "serious_step"),
         manip_condes_catdes = structure(list(id = "manip_condes_catdes",
                                              title = "L'Usine `a Prompts", section = "r_sorties",
                                              objective = "Inspecter et transformer les sorties condes/catdes en texte exploitable.",
                                              text = NULL, code = "# ============================================================\n# Case 11 : manipuler les sorties condes/catdes\n# ============================================================\n\n# Objectif de cette case :\n# appliquer aux sorties condes() et catdes() la m^eme logique\n# que celle utilis'ee pour LinearModel() et AovSum().\n#\n# Mais ici, les objets sont plus riches :\n# ils contiennent plusieurs niveaux d information.\n# Il faut donc les inspecter avant de les transformer en texte.\n\nobjets_requis <- c('res_condes', 'res_catdes')\n\nobjets_absents <- objets_requis[\n  !vapply(\n    objets_requis,\n    exists,\n    logical(1),\n    envir = .GlobalEnv,\n    inherits = FALSE\n  )\n]\n\nif (length(objets_absents) > 0) {\n  stop(\n    'Objets absents : ',\n    paste(objets_absents, collapse = ', '),\n    '. Ex'ecute d abord les cases condes et catdes.',\n    call. = FALSE\n  )\n}\n\n# ------------------------------------------------------------\n# 1. Inspecter les objets retourn'es par condes() et catdes()\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('1. Que contient l objet res_condes ?\\n')\ncat('Commande : names(res_condes)\\n')\ncat('============================================================\\n')\nprint(names(res_condes))\n\ncat('\\n============================================================\\n')\ncat('2. Que contient l objet res_catdes ?\\n')\ncat('Commande : names(res_catdes)\\n')\ncat('============================================================\\n')\nprint(names(res_catdes))\n\n\n# ------------------------------------------------------------\n# 2. Observer la structure sans tout afficher\n# ------------------------------------------------------------\n\n# str() est utile pour comprendre la structure d un objet R.\n# max.level = 2 'evite d afficher trop de d'etails.\n\ncat('\\n============================================================\\n')\ncat('3. Structure simplifi'ee de res_condes\\n')\ncat('Commande : str(res_condes, max.level = 2)\\n')\ncat('============================================================\\n')\nstr(res_condes, max.level = 2)\n\ncat('\\n============================================================\\n')\ncat('4. Structure simplifi'ee de res_catdes\\n')\ncat('Commande : str(res_catdes, max.level = 2)\\n')\ncat('============================================================\\n')\nstr(res_catdes, max.level = 2)\n\n\n# ------------------------------------------------------------\n# 3. Capturer les sorties compl`etes sous forme de texte\n# ------------------------------------------------------------\n\ntexte_condes <- paste(\n  capture.output(print(res_condes)),\n  collapse = '\\n'\n)\n\ntexte_catdes <- paste(\n  capture.output(print(res_catdes)),\n  collapse = '\\n'\n)\n\ncat('\\n============================================================\\n')\ncat('5. Sorties captur'ees sous forme de texte\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : texte_condes\\n')\ncat('Longueur : ', nchar(texte_condes), ' caract`eres\\n', sep = '')\ncat('\\n')\ncat('Objet cr'e'e : texte_catdes\\n')\ncat('Longueur : ', nchar(texte_catdes), ' caract`eres\\n', sep = '')\n\n\n# ------------------------------------------------------------\n# 4. Afficher un apercu contr^ol'e des textes captur'es\n# ------------------------------------------------------------\n\nafficher_apercu_texte <- function(titre, nom_objet, texte, n = 1200) {\n  cat('\\n============================================================\\n')\n  cat(titre, '\\n')\n  cat('Objet affich'e : ', nom_objet, '\\n', sep = '')\n  cat('============================================================\\n')\n  cat(substr(texte, 1, n))\n\n  if (nchar(texte) > n) {\n    cat('\\n\\n[... texte tronqu'e dans l affichage ...]\\n')\n    cat('Longueur totale : ', nchar(texte), ' caract`eres\\n', sep = '')\n  }\n}\n\nafficher_apercu_texte(\n  titre = 'Apercu du texte captur'e pour condes()',\n  nom_objet = 'texte_condes',\n  texte = texte_condes\n)\n\nafficher_apercu_texte(\n  titre = 'Apercu du texte captur'e pour catdes()',\n  nom_objet = 'texte_catdes',\n  texte = texte_catdes\n)\n\n\n# ------------------------------------------------------------\n# 5. Construire une fonction pour produire un prompt\n# ------------------------------------------------------------\n\n# On 'evite de r'e'ecrire deux fois la m^eme structure de prompt.\n# On cr'ee une fonction qui recoit :\n# - un titre ;\n# - la variable d'ecrite ;\n# - le texte statistique captur'e ;\n# - des consignes sp'ecifiques.\n\nconstruire_prompt_description <- function(titre,\n                                          variable_decrite,\n                                          type_variable,\n                                          texte_sortie,\n                                          consignes) {\n\n  paste(\n    titre,\n    '',\n    paste0('Variable d'ecrite : ', variable_decrite, '.'),\n    paste0('Type de variable d'ecrite : ', type_variable, '.'),\n    '',\n    'Sortie statistique utilis'ee :',\n    texte_sortie,\n    '',\n    'Consignes :',\n    paste0('- ', consignes, collapse = '\\n'),\n    sep = '\\n'\n  )\n}\n\ncat('\\n============================================================\\n')\ncat('6. Fonction de construction de prompt\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : construire_prompt_description()\\n')\ncat('R^ole : produire un prompt `a partir d une sortie statistique captur'ee.\\n')\n\n\n# ------------------------------------------------------------\n# 6. Construire le prompt pour condes()\n# ------------------------------------------------------------\n\nconsignes_condes <- c(\n  'identifier les variables les plus li'ees `a intention_achat',\n  'distinguer variables quantitatives et variables qualitatives',\n  'interpr'eter les associations sans parler de causalit'e',\n  'produire une synth`ese courte et structur'ee'\n)\n\nprompt_condes <- construire_prompt_description(\n  titre = '# Interpr'etation de condes()',\n  variable_decrite = 'intention_achat',\n  type_variable = 'quantitative',\n  texte_sortie = texte_condes,\n  consignes = consignes_condes\n)\n\ncat('\\n============================================================\\n')\ncat('7. Prompt construit pour condes()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : prompt_condes\\n')\ncat('Variable d'ecrite : intention_achat\\n')\n\n\n# ------------------------------------------------------------\n# 7. Construire le prompt pour catdes()\n# ------------------------------------------------------------\n\nconsignes_catdes <- c(\n  'd'ecrire chaque profil alimentaire',\n  's'eparer les preuves quantitatives et les modalit'es qualitatives',\n  'ne pas surinterpr'eter les associations faibles',\n  'proposer une synth`ese lisible des profils'\n)\n\nprompt_catdes <- construire_prompt_description(\n  titre = '# Interpr'etation de catdes()',\n  variable_decrite = 'profil_alim',\n  type_variable = 'qualitative',\n  texte_sortie = texte_catdes,\n  consignes = consignes_catdes\n)\n\ncat('\\n============================================================\\n')\ncat('8. Prompt construit pour catdes()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : prompt_catdes\\n')\ncat('Variable d'ecrite : profil_alim\\n')\n\n\n# ------------------------------------------------------------\n# 8. Afficher un apercu des prompts\n# ------------------------------------------------------------\n\nafficher_apercu_prompt <- function(titre, nom_objet, prompt, n = 1500) {\n  cat('\\n============================================================\\n')\n  cat(titre, '\\n')\n  cat('Objet affich'e : ', nom_objet, '\\n', sep = '')\n  cat('============================================================\\n')\n  cat(substr(prompt, 1, n))\n\n  if (nchar(prompt) > n) {\n    cat('\\n\\n[... prompt tronqu'e dans l affichage ...]\\n')\n    cat('Longueur totale : ', nchar(prompt), ' caract`eres\\n', sep = '')\n  }\n}\n\nafficher_apercu_prompt(\n  titre = 'Apercu du prompt condes()',\n  nom_objet = 'prompt_condes',\n  prompt = prompt_condes\n)\n\nafficher_apercu_prompt(\n  titre = 'Apercu du prompt catdes()',\n  nom_objet = 'prompt_catdes',\n  prompt = prompt_catdes\n)\n\n\n# ------------------------------------------------------------\n# 9. R'esum'e p'edagogique de la case\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- texte_condes : sortie compl`ete de condes() transform'ee en texte\\n')\ncat('- texte_catdes : sortie compl`ete de catdes() transform'ee en texte\\n')\ncat('- construire_prompt_description() : fonction g'en'erique de construction de prompt\\n')\ncat('- consignes_condes : consignes utilis'ees pour interpr'eter condes()\\n')\ncat('- consignes_catdes : consignes utilis'ees pour interpr'eter catdes()\\n')\ncat('- prompt_condes : prompt construit pour la variable quantitative intention_achat\\n')\ncat('- prompt_catdes : prompt construit pour la variable qualitative profil_alim\\n')\ncat('\\n')\ncat('Id'ee cl'e : on sait maintenant transformer des sorties FactoMineR riches\\n')\ncat('en prompts structur'es. C est pr'ecis'ement ce que NaileR va syst'ematiser.\\n')",
                                              code_display = "# Inspecter les objets retourn'es par condes() et catdes()\n\nnames(res_condes)\nnames(res_catdes)\n\n# Observer leur structure sans tout afficher\n\nstr(res_condes, max.level = 2)\nstr(res_catdes, max.level = 2)\n\n# Capturer les sorties compl`etes sous forme de texte\n\ntexte_condes <- paste(\ncapture.output(print(res_condes)),\ncollapse = '\n'\n)\n\ntexte_catdes <- paste(\ncapture.output(print(res_catdes)),\ncollapse = '\n'\n)\n\n# V'erifier les textes captur'es\n\nnchar(texte_condes)\nnchar(texte_catdes)\n\nsubstr(texte_condes, 1, 1200)\nsubstr(texte_catdes, 1, 1200)\n\n# Construire une fonction g'en'erique pour produire un prompt\n\nconstruire_prompt_description <- function(titre,\nvariable_decrite,\ntype_variable,\ntexte_sortie,\nconsignes) {\n\npaste(\ntitre,\n'',\npaste0('Variable d'ecrite : ', variable_decrite, '.'),\npaste0('Type de variable d'ecrite : ', type_variable, '.'),\n'',\n'Sortie statistique utilis'ee :',\ntexte_sortie,\n'',\n'Consignes :',\npaste0('- ', consignes, collapse = '\n'),\nsep = '\n'\n)\n}\n\n# D'efinir les consignes pour condes()\n\nconsignes_condes <- c(\n'identifier les variables les plus li'ees `a intention_achat',\n'distinguer variables quantitatives et variables qualitatives',\n'interpr'eter les associations sans parler de causalit'e',\n'produire une synth`ese courte et structur'ee'\n)\n\n# Construire le prompt pour condes()\n\nprompt_condes <- construire_prompt_description(\ntitre = '# Interpr'etation de condes()',\nvariable_decrite = 'intention_achat',\ntype_variable = 'quantitative',\ntexte_sortie = texte_condes,\nconsignes = consignes_condes\n)\n\n# D'efinir les consignes pour catdes()\n\nconsignes_catdes <- c(\n'd'ecrire chaque profil alimentaire',\n's'eparer les preuves quantitatives et les modalit'es qualitatives',\n'ne pas surinterpr'eter les associations faibles',\n'proposer une synth`ese lisible des profils'\n)\n\n# Construire le prompt pour catdes()\n\nprompt_catdes <- construire_prompt_description(\ntitre = '# Interpr'etation de catdes()',\nvariable_decrite = 'profil_alim',\ntype_variable = 'qualitative',\ntexte_sortie = texte_catdes,\nconsignes = consignes_catdes\n)\n\n# Examiner les prompts construits\n\nsubstr(prompt_condes, 1, 1500)\nnchar(prompt_condes)\n\nsubstr(prompt_catdes, 1, 1500)\nnchar(prompt_catdes)",
                                              expected_output = "Des textes et prompts issus de condes/catdes : `texte_condes`, `texte_catdes`, `prompt_condes`, `prompt_catdes`, construits de mani`ere plus g'en'erique.",
                                              transition = "NaileR prolonge cette logique en produisant des artefacts et prompts plus contr^ol'es.",
                                              outputs = "console", question = "Quel objet contient la sortie textuelle captur'ee `a partir de catdes() ?",
                                              expected_answer = "texte_catdes", validator = NULL, pdf = NULL,
                                              pdf_on_run = NULL, next_steps = "nailer_presentation",
                                              prerequisites = character(0), concepts = character(0),
                                              layout = list(x = 260, y = 210)), class = "serious_step"),
         nailer_presentation = structure(list(id = "nailer_presentation",
                                              title = "L'Arsenal NaileR", section = "entrainer", objective = "Pr'esenter le r^ole de NaileR dans le workflow : de FactoMineR aux prompts, puis aux variables latentes et aux textes.",
                                              text = NULL, code = "# ============================================================\n# Case 12a : pr'esenter le package NaileR\n# ============================================================\n\n# Objectif de cette case :\n# prendre du recul apr`es un premier exemple avec nail_catdes().\n#\n# NaileR est pr'esent'e ici comme un package qui prolonge\n# les sorties de FactoMineR vers des prompts, artefacts\n# et interpr'etations contr^ol'ees.\n\n# ------------------------------------------------------------\n# 1. V'erifier les fonctions disponibles\n# ------------------------------------------------------------\n\nnailer_disponible <- requireNamespace('NaileR', quietly = TRUE)\n\nif (nailer_disponible) {\n\n  exports_nailer <- getNamespaceExports('NaileR')\n\n  fonctions_nailer <- grep(\n    '^nail_',\n    exports_nailer,\n    value = TRUE\n  )\n\n} else {\n\n  exports_nailer <- character(0)\n\n  fonctions_nailer <- c(\n    'nail_condes',\n    'nail_catdes',\n    'nail_textual',\n    'nail_textual_prep',\n    'nail_textual_contextualized'\n  )\n}\n\nfonctions_nailer_df <- data.frame(\n  fonction = fonctions_nailer,\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('1. Fonctions NaileR rep'er'ees ou attendues\\n')\ncat('============================================================\\n')\ncat('Package NaileR install'e : ', nailer_disponible, '\\n', sep = '')\ncat('Objet cr'e'e : fonctions_nailer\\n')\nprint(fonctions_nailer_df, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 2. Situer NaileR dans le workflow du tutoriel\n# ------------------------------------------------------------\n\nschema_nailer <- data.frame(\n  etape = c(\n    'FactoMineR',\n    'R',\n    'Prompt manuel',\n    'NaileR',\n    'LLM 'eventuel'\n  ),\n  role = c(\n    'produire des sorties statistiques structur'ees',\n    'inspecter, extraire et transformer les objets',\n    'construire une demande interpr'etative contr^ol'ee',\n    'syst'ematiser la production de prompts et d artefacts',\n    'g'en'erer une interpr'etation `a partir d un prompt contr^ol'e'\n  ),\n  exemple = c(\n    'catdes(), condes(), PCA(), HCPC()',\n    'names(), str(), capture.output(), paste()',\n    'prompt_catdes, prompt_condes',\n    'nail_catdes(), nail_condes(), nail_textual()',\n    'Ollama, Gemini ou autre moteur'\n  ),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('2. Place de NaileR dans le workflow\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : schema_nailer\\n')\nprint(schema_nailer, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 3. Distinguer EnTraineR et NaileR\n# ------------------------------------------------------------\n\ncomparaison_entrainer_nailer <- data.frame(\n  package = c('EnTraineR', 'NaileR'),\n  point_de_depart = c(\n    'analyses statistiques simples ou p'edagogiques',\n    'sorties FactoMineR plus riches et objets descriptifs'\n  ),\n  objectif = c(\n    'apprendre `a construire et contr^oler des prompts statistiques',\n    'produire des prompts et artefacts `a partir de sorties complexes'\n  ),\n  exemples = c(\n    'r'egression, ANOVA, corr'elation, tests',\n    'condes, catdes, dimensions latentes, classes, verbatims'\n  ),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('3. Diff'erence p'edagogique entre EnTraineR et NaileR\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : comparaison_entrainer_nailer\\n')\nprint(comparaison_entrainer_nailer, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 4. Pr'eparer la suite : explicite vers latent\n# ------------------------------------------------------------\n\nflow_suivant_nailer <- data.frame(\n  objet = c(\n    'variable qualitative explicite',\n    'variable de classe latente',\n    'dimension factorielle',\n    'verbatims par classe',\n    'synth`ese statistique + textuelle'\n  ),\n  exemple = c(\n    'profil_alim',\n    'classe_hcpc',\n    'Dim.1 issue de l ACP',\n    'commentaires regroup'es par classe',\n    'interpr'etation finale des profils'\n  ),\n  fonction_ou_logique = c(\n    'nail_catdes()',\n    'catdes() puis logique NaileR',\n    'condes() puis prompt latent',\n    'nail_textual() / nail_textual_prep()',\n    'nail_textual_contextualized()'\n  ),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('4. Suite du workflow : de l explicite au latent\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : flow_suivant_nailer\\n')\nprint(flow_suivant_nailer, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 5. Message p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e p'edagogique\\n')\ncat('============================================================\\n')\ncat('NaileR ne remplace pas FactoMineR.\\n')\ncat('NaileR prolonge les sorties de FactoMineR.\\n')\ncat('\\n')\ncat('Dans les cases pr'ec'edentes, nous avons construit la logique `a la main :\\n')\ncat('1. produire une sortie statistique ;\\n')\ncat('2. r'ecup'erer cette sortie dans R ;\\n')\ncat('3. transformer cette sortie en texte ;\\n')\ncat('4. construire un prompt contr^ol'e.\\n')\ncat('\\n')\ncat('La case suivante montrera un premier exemple de cette automatisation avec nail_catdes().\\n')\ncat('La suite du tutoriel va d'eplacer cette logique vers des objets moins explicites :\\n')\ncat('- classes issues d une classification ;\\n')\ncat('- dimensions factorielles ;\\n')\ncat('- profils textuels ;\\n')\ncat('- interpr'etation de variables latentes.\\n')\n\n\n# ------------------------------------------------------------\n# 6. Objets disponibles pour la suite\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('Objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- fonctions_nailer : fonctions nail_* rep'er'ees ou attendues\\n')\ncat('- schema_nailer : place de NaileR dans le workflow\\n')\ncat('- comparaison_entrainer_nailer : distinction EnTraineR / NaileR\\n')\ncat('- flow_suivant_nailer : transition vers latent et donn'ees textuelles\\n')",
                                              code_display = "# V'erifier si NaileR est disponible\n\nnailer_disponible <- requireNamespace('NaileR', quietly = TRUE)\n\nif (nailer_disponible) {\n\nexports_nailer <- getNamespaceExports('NaileR')\n\nfonctions_nailer <- grep(\n'^nail_',\nexports_nailer,\nvalue = TRUE\n)\n\n} else {\n\nexports_nailer <- character(0)\n\nfonctions_nailer <- c(\n'nail_condes',\n'nail_catdes',\n'nail_textual',\n'nail_textual_prep',\n'nail_textual_contextualized'\n)\n}\n\nfonctions_nailer_df <- data.frame(\nfonction = fonctions_nailer,\nstringsAsFactors = FALSE\n)\n\nnailer_disponible\nfonctions_nailer_df\n\n# Situer NaileR dans le workflow du tutoriel\n\nschema_nailer <- data.frame(\netape = c(\n'FactoMineR',\n'R',\n'Prompt manuel',\n'NaileR',\n'LLM 'eventuel'\n),\nrole = c(\n'produire des sorties statistiques structur'ees',\n'inspecter, extraire et transformer les objets',\n'construire une demande interpr'etative contr^ol'ee',\n'syst'ematiser la production de prompts et d artefacts',\n'g'en'erer une interpr'etation `a partir d un prompt contr^ol'e'\n),\nexemple = c(\n'catdes(), condes(), PCA(), HCPC()',\n'names(), str(), capture.output(), paste()',\n'prompt_catdes, prompt_condes',\n'nail_catdes(), nail_condes(), nail_textual()',\n'Ollama, Gemini ou autre moteur'\n),\nstringsAsFactors = FALSE\n)\n\nschema_nailer\n\n# Distinguer EnTraineR et NaileR\n\ncomparaison_entrainer_nailer <- data.frame(\npackage = c('EnTraineR', 'NaileR'),\npoint_de_depart = c(\n'analyses statistiques simples ou p'edagogiques',\n'sorties FactoMineR plus riches et objets descriptifs'\n),\nobjectif = c(\n'apprendre `a construire et contr^oler des prompts statistiques',\n'produire des prompts et artefacts `a partir de sorties complexes'\n),\nexemples = c(\n'r'egression, ANOVA, corr'elation, tests',\n'condes, catdes, dimensions latentes, classes, verbatims'\n),\nstringsAsFactors = FALSE\n)\n\ncomparaison_entrainer_nailer\n\n# Pr'eparer la suite : de l explicite vers le latent et le textuel\n\nflow_suivant_nailer <- data.frame(\nobjet = c(\n'variable qualitative explicite',\n'variable de classe latente',\n'dimension factorielle',\n'verbatims par classe',\n'synth`ese statistique + textuelle'\n),\nexemple = c(\n'profil_alim',\n'classe_hcpc',\n'Dim.1 issue de l ACP',\n'commentaires regroup'es par classe',\n'interpr'etation finale des profils'\n),\nfonction_ou_logique = c(\n'nail_catdes()',\n'catdes() puis logique NaileR',\n'condes() puis prompt latent',\n'nail_textual() / nail_textual_prep()',\n'nail_textual_contextualized()'\n),\nstringsAsFactors = FALSE\n)\n\nflow_suivant_nailer",
                                              expected_output = "Une pr'esentation structur'ee de NaileR : fonctions, r^ole dans le workflow, diff'erence avec EnTraineR et transition vers les variables latentes et les textes.",
                                              transition = "On passe ensuite au flow : variable de classe latente, description statistique et analyse textuelle.",
                                              outputs = "console", question = "Quel package prolonge les sorties FactoMineR vers des prompts et artefacts interpr'etables ?",
                                              expected_answer = "nailer", validator = NULL, pdf = NULL,
                                              pdf_on_run = "NaileR.pdf", next_steps = "nailer_catdes_exemple",
                                              prerequisites = character(0), concepts = character(0),
                                              layout = list(x = 0, y = 210)), class = "serious_step"),
         nailer_catdes_exemple = structure(list(id = "nailer_catdes_exemple",
                                                title = "L''Epreuve NaileR", section = "entrainer", objective = "Utiliser nail_catdes() sur une variable qualitative du jeu de donn'ees.",
                                                text = NULL, code = "# ============================================================\n# Case 12b : premier exemple avec NaileR et nail_catdes()\n# ============================================================\n\n# Objectif de cette case :\n# utiliser NaileR sur une variable qualitative d'ej`a d'ecrite par catdes().\n#\n# Jusqu ici, nous avons fait `a la main :\n# 1. catdes() pour d'ecrire profil_alim ;\n# 2. capture.output() pour transformer la sortie en texte ;\n# 3. paste() pour construire un prompt.\n#\n# nail_catdes() vise `a syst'ematiser cette logique.\n\nobjets_requis <- c(\n  'questionnaire_desc',\n  'res_catdes',\n  'texte_catdes'\n)\n\nobjets_absents <- objets_requis[\n  !vapply(\n    objets_requis,\n    exists,\n    logical(1),\n    envir = .GlobalEnv,\n    inherits = FALSE\n  )\n]\n\nif (length(objets_absents) > 0) {\n  stop(\n    'Objets absents : ',\n    paste(objets_absents, collapse = ', '),\n    '. Ex'ecute d abord les cases catdes et Usine `a Prompts.',\n    call. = FALSE\n  )\n}\n\n# ------------------------------------------------------------\n# 1. V'erifier la disponibilit'e de NaileR\n# ------------------------------------------------------------\n\nnailer_disponible <- requireNamespace('NaileR', quietly = TRUE)\n\ncat('\\n============================================================\\n')\ncat('1. Disponibilit'e de NaileR\\n')\ncat('============================================================\\n')\ncat('Package NaileR install'e : ', nailer_disponible, '\\n', sep = '')\n\n\n# ------------------------------------------------------------\n# 2. D'efinir la variable qualitative `a d'ecrire\n# ------------------------------------------------------------\n\nvar_catdes_nailer <- 'profil_alim'\n\nnum_var_catdes_nailer <- which(\n  names(questionnaire_desc) == var_catdes_nailer\n)\n\ncat('\\n============================================================\\n')\ncat('2. Variable qualitative d'ecrite\\n')\ncat('============================================================\\n')\ncat('Variable d'ecrite : ', var_catdes_nailer, '\\n', sep = '')\ncat('Position dans questionnaire_desc : ', num_var_catdes_nailer, '\\n', sep = '')\n\ncat('\\nR'epartition de la variable :\\n')\nprint(table(questionnaire_desc[[var_catdes_nailer]]))\n\n\n# ------------------------------------------------------------\n# 3. Rappeler le travail fait `a la main\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('3. Ce que nous avons d'ej`a construit `a la main\\n')\ncat('============================================================\\n')\ncat('Objet res_catdes      : sortie FactoMineR::catdes()\\n')\ncat('Objet texte_catdes    : sortie catdes() transform'ee en texte\\n')\ncat('Objet prompt_catdes   : prompt construit `a la main\\n')\n\nif (exists('prompt_catdes')) {\n  cat('\\nApercu du prompt manuel prompt_catdes :\\n\\n')\n  cat(substr(prompt_catdes, 1, 1000))\n\n  if (nchar(prompt_catdes) > 1000) {\n    cat('\\n\\n[... prompt manuel tronqu'e dans l affichage ...]\\n')\n  }\n}\n\n\n# ------------------------------------------------------------\n# 4. Appeler nail_catdes() si NaileR est disponible\n# ------------------------------------------------------------\n\nres_nail_catdes <- NULL\n\nif (nailer_disponible) {\n\n  exports_nailer <- getNamespaceExports('NaileR')\n\n  if ('nail_catdes' %in% exports_nailer) {\n\n    cat('\\n============================================================\\n')\n    cat('4. Appel de NaileR::nail_catdes()\\n')\n    cat('============================================================\\n')\n    cat('Commande ex'ecut'ee :\\n')\n    cat('NaileR::nail_catdes(questionnaire_desc, num.var = num_var_catdes_nailer, generate = FALSE)\\n')\n\n    res_nail_catdes <- tryCatch(\n      NaileR::nail_catdes(\n        questionnaire_desc,\n        num.var = num_var_catdes_nailer,\n        generate = FALSE\n      ),\n      error = function(e) {\n        paste('nail_catdes non ex'ecut'e :', conditionMessage(e))\n      }\n    )\n\n  } else {\n\n    res_nail_catdes <- 'La fonction nail_catdes() n est pas export'ee par cette version de NaileR.'\n  }\n\n} else {\n\n  res_nail_catdes <- 'NaileR n est pas install'e : on conserve le prompt manuel prompt_catdes comme point de comparaison.'\n}\n\n\n# ------------------------------------------------------------\n# 5. Inspecter l objet retourn'e sans l afficher brutalement\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('5. Objet retourn'e par nail_catdes()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_nail_catdes\\n')\ncat('Classe de l objet : ', paste(class(res_nail_catdes), collapse = ', '), '\\n', sep = '')\n\nif (is.list(res_nail_catdes)) {\n  cat('Champs disponibles :\\n')\n  print(names(res_nail_catdes))\n} else {\n  cat('Objet non list'e ou message de repli :\\n')\n  cat(as.character(res_nail_catdes), '\\n')\n}\n\n\n# ------------------------------------------------------------\n# 6. Essayer d extraire un prompt depuis l objet NaileR\n# ------------------------------------------------------------\n\nextraire_champ_possible <- function(objet, noms_possibles) {\n\n  if (!is.list(objet)) {\n    return(NULL)\n  }\n\n  noms_objet <- names(objet)\n\n  if (is.null(noms_objet)) {\n    return(NULL)\n  }\n\n  for (nom in noms_possibles) {\n    if (nom %in% noms_objet) {\n      return(objet[[nom]])\n    }\n  }\n\n  NULL\n}\n\nprompt_nail_catdes <- extraire_champ_possible(\n  res_nail_catdes,\n  c('prompt', 'prompts', 'request', 'text_prompt')\n)\n\ncat('\\n============================================================\\n')\ncat('6. Prompt 'eventuellement produit par nail_catdes()\\n')\ncat('============================================================\\n')\n\nif (!is.null(prompt_nail_catdes)) {\n\n  prompt_nail_catdes <- paste(\n    capture.output(print(prompt_nail_catdes)),\n    collapse = '\\n'\n  )\n\n  cat('Objet cr'e'e : prompt_nail_catdes\\n')\n  cat('Apercu :\\n\\n')\n  cat(substr(prompt_nail_catdes, 1, 1500))\n\n  if (nchar(prompt_nail_catdes) > 1500) {\n    cat('\\n\\n[... prompt NaileR tronqu'e dans l affichage ...]\\n')\n    cat('Longueur totale : ', nchar(prompt_nail_catdes), ' caract`eres\\n', sep = '')\n  }\n\n} else {\n\n  cat('Aucun champ prompt standard d'etect'e dans res_nail_catdes.\\n')\n  cat('Ce n est pas bloquant : l objet complet reste disponible pour inspection.\\n')\n}\n\n\n# ------------------------------------------------------------\n# 7. Comparaison p'edagogique\n# ------------------------------------------------------------\n\ncomparaison_catdes_nailer <- data.frame(\n  etape = c(\n    'catdes()',\n    'capture.output()',\n    'prompt manuel',\n    'nail_catdes()'\n  ),\n  role = c(\n    'd'ecrire statistiquement une variable qualitative',\n    'transformer la sortie en texte',\n    'organiser une demande interpr'etative',\n    'syst'ematiser cette logique dans NaileR'\n  ),\n  objet = c(\n    'res_catdes',\n    'texte_catdes',\n    'prompt_catdes',\n    'res_nail_catdes'\n  ),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('7. Comparaison avec le travail manuel\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : comparaison_catdes_nailer\\n')\nprint(comparaison_catdes_nailer, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 8. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e : objets disponibles pour la suite\\n')\ncat('============================================================\\n')\ncat('- var_catdes_nailer : variable qualitative d'ecrite\\n')\ncat('- num_var_catdes_nailer : position de cette variable dans questionnaire_desc\\n')\ncat('- res_nail_catdes : r'esultat ou message issu de nail_catdes()\\n')\ncat('- prompt_nail_catdes : prompt extrait si disponible\\n')\ncat('- comparaison_catdes_nailer : comparaison entre travail manuel et NaileR\\n')\ncat('\\n')\ncat('Id'ee cl'e : nail_catdes() prolonge le travail manuel r'ealis'e autour de catdes().\\n')\ncat('La case suivante passe de la variable explicite profil_alim `a une classe latente construite par ACP + HCPC.\\n')",
                                                code_display = "# V'erifier la disponibilit'e de NaileR\n\nnailer_disponible <- requireNamespace('NaileR', quietly = TRUE)\n\nnailer_disponible\n\n# D'efinir la variable qualitative `a d'ecrire\n\nvar_catdes_nailer <- 'profil_alim'\n\nnum_var_catdes_nailer <- which(\nnames(questionnaire_desc) == var_catdes_nailer\n)\n\nvar_catdes_nailer\nnum_var_catdes_nailer\n\n# Examiner la r'epartition de la variable\n\ntable(questionnaire_desc[[var_catdes_nailer]])\n\n# Rappeler le travail fait `a la main\n\nres_catdes\ntexte_catdes\n\nif (exists('prompt_catdes')) {\nsubstr(prompt_catdes, 1, 1000)\nnchar(prompt_catdes)\n}\n\n# Appeler nail_catdes() si NaileR est disponible\n\nres_nail_catdes <- NULL\n\nif (nailer_disponible) {\n\nexports_nailer <- getNamespaceExports('NaileR')\n\nif ('nail_catdes' %in% exports_nailer) {\n\nres_nail_catdes <- tryCatch(\n  NaileR::nail_catdes(\n    questionnaire_desc,\n    num.var = num_var_catdes_nailer,\n    generate = FALSE\n  ),\n  error = function(e) {\n    paste('nail_catdes non ex'ecut'e :', conditionMessage(e))\n  }\n)\n\n} else {\n\nres_nail_catdes <- 'La fonction nail_catdes() n est pas export'ee par cette version de NaileR.'\n\n}\n\n} else {\n\nres_nail_catdes <- 'NaileR n est pas install'e : on conserve le prompt manuel prompt_catdes comme point de comparaison.'\n}\n\n# Inspecter l objet retourn'e\n\nclass(res_nail_catdes)\n\nif (is.list(res_nail_catdes)) {\nnames(res_nail_catdes)\n} else {\nres_nail_catdes\n}\n\n# Fonction utilitaire pour extraire un champ possible\n\nextraire_champ_possible <- function(objet, noms_possibles) {\n\nif (!is.list(objet)) {\nreturn(NULL)\n}\n\nnoms_objet <- names(objet)\n\nif (is.null(noms_objet)) {\nreturn(NULL)\n}\n\nfor (nom in noms_possibles) {\nif (nom %in% noms_objet) {\nreturn(objet[[nom]])\n}\n}\n\nNULL\n}\n\n# Essayer d extraire le prompt produit par nail_catdes()\n\nprompt_nail_catdes <- extraire_champ_possible(\nres_nail_catdes,\nc('prompt', 'prompts', 'request', 'text_prompt')\n)\n\nif (!is.null(prompt_nail_catdes)) {\n\nprompt_nail_catdes <- paste(\nas.character(prompt_nail_catdes),\ncollapse = '\n'\n)\n\nsubstr(prompt_nail_catdes, 1, 1500)\nnchar(prompt_nail_catdes)\n}\n\n# Comparer le travail manuel et l automatisation NaileR\n\ncomparaison_catdes_nailer <- data.frame(\netape = c(\n'catdes()',\n'capture.output()',\n'prompt manuel',\n'nail_catdes()'\n),\nrole = c(\n'd'ecrire statistiquement une variable qualitative',\n'transformer la sortie en texte',\n'organiser une demande interpr'etative',\n'syst'ematiser cette logique dans NaileR'\n),\nobjet = c(\n'res_catdes',\n'texte_catdes',\n'prompt_catdes',\n'res_nail_catdes'\n),\nstringsAsFactors = FALSE\n)\n\ncomparaison_catdes_nailer",
                                                expected_output = "Un premier exemple de `nail_catdes()` appliqu'e `a `profil_alim`, avec comparaison entre le travail manuel et l'automatisation NaileR.",
                                                transition = "On passe maintenant des variables explicites aux classes latentes construites par ACP et HCPC.",
                                                outputs = "console", question = "Quelle fonction NaileR utilise-t-on ici pour prolonger catdes() ?",
                                                expected_answer = "nail_catdes", validator = NULL, pdf = NULL,
                                                pdf_on_run = "nailer_exemple.pdf", next_steps = "acp_hcpc_classes",
                                                prerequisites = character(0), concepts = character(0),
                                                layout = list(x = 0, y = 420)), class = "serious_step"),
         acp_hcpc_classes = structure(list(id = "acp_hcpc_classes",
                                           title = "Le Sommet Latent", section = "stat", objective = "Construire une variable de classe (latente) `a partir de variables actives.",
                                           text = NULL, code = "# ============================================================\n# Case 13 : construire une classe latente par ACP + HCPC\n# ============================================================\n\n# Objectif de cette case :\n# passer d un questionnaire avec des variables explicites\n# `a une variable de classe, latente (implicite).\n#\n# Ici, on r'ealise :\n# - une ACP sur des variables quantitatives actives ;\n# - une classification ascendante hi'erarchiques sur les coordonn'ees factorielles.\n#\n# On obtient une variable de classe. Cette variable n 'etait pas directement pos'ee\n# dans le questionnaire. Elle est construite par l analyse : c est pourquoi on parlera\n# de variable de classe latente ou de classe construite.\n\n# ------------------------------------------------------------\n# 1. V'erifier les pr'erequis\n# ------------------------------------------------------------\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\n    call. = FALSE\n  )\n}\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop(\n    'Le package FactoMineR est n'ecessaire pour cette case.',\n    call. = FALSE\n  )\n}\n\n\n# -----------------------------------------------------------------\n# 2. D'efinir les variables actives qui vont construire la typologie\n# -----------------------------------------------------------------\n\nvariables_typologie <- c(\n  'attention_prix',\n  'contrainte_temps',\n  'cuisine_maison',\n  'lecture_labels',\n  'achat_local',\n  'ouverture_innovation',\n  'usage_appli_alim',\n  'preoccupation_sante',\n  'autonomie_alimentaire',\n  'confiance_labels'\n)\n\nvariables_absentes <- setdiff(\n  variables_typologie,\n  names(questionnaire)\n)\n\nif (length(variables_absentes) > 0) {\n  stop(\n    'Variables de typologie absentes du questionnaire : ',\n    paste(variables_absentes, collapse = ', '),\n    call. = FALSE\n  )\n}\n\ncat('\\n============================================================\\n')\ncat('1. Variables actives de typologie\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : variables_typologie\\n')\nprint(variables_typologie)\n\n\n# ------------------------------------------------------------\n# 3. Pr'eparer le tableau actif\n# ------------------------------------------------------------\n\ndonnees_typologie <- questionnaire[, variables_typologie]\n\nvariables_non_numeriques <- names(donnees_typologie)[\n  !vapply(donnees_typologie, is.numeric, logical(1))\n]\n\nif (length(variables_non_numeriques) > 0) {\n  stop(\n    'Les variables suivantes ne sont pas num'eriques : ',\n    paste(variables_non_numeriques, collapse = ', '),\n    '. Une ACP n'ecessite ici des variables quantitatives.',\n    call. = FALSE\n  )\n}\n\ncat('\\n============================================================\\n')\ncat('2. Tableau actif pour ACP et HCPC\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : donnees_typologie\\n')\ncat('Nombre de lignes : ', nrow(donnees_typologie), '\\n', sep = '')\ncat('Nombre de variables actives : ', ncol(donnees_typologie), '\\n', sep = '')\n\ncat('\\nApercu des premi`eres lignes :\\n')\nprint(head(donnees_typologie, 3))\n\n\ncat('\\n============================================================\\n')\ncat('Transition : de NaileR aux classes latentes\\n')\ncat('============================================================\\n')\ncat('Nous avons vu que NaileR peut prolonger des fonctions de FactoMineR comme catdes().\\n')\ncat('Jusqu ici, nous avons surtout travaill'e avec des variables explicites.\\n')\ncat('Pour appliquer cette logique `a une variable latente, il faut d abord la construire.\\n')\ncat('C est le r^ole de cette case : cr'eer classe_hcpc par ACP + HCPC.\\n')\n\n# ------------------------------------------------------------\n# 4. R'ealiser l ACP\n# ------------------------------------------------------------\n\nres_pca <- FactoMineR::PCA(\n  donnees_typologie,\n  scale.unit = TRUE,\n  graph = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('3. ACP sur les variables de typologie\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_pca\\n')\n\ncat('\\nValeurs propres et pourcentages d inertie :\\n')\nprint(res_pca$eig)\n\n\n# ------------------------------------------------------------\n# 5. R'ealiser la classification HCPC\n# ------------------------------------------------------------\n\nset.seed(123)\n\nres_hcpc <- FactoMineR::HCPC(\n  res_pca,\n  nb.clust = 3,\n  graph = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('4. Classification HCPC\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_hcpc\\n')\ncat('Variable cr'e'ee : res_hcpc$data.clust$clust\\n')\n\ncat('\\nR'epartition des classes :\\n')\nprint(table(res_hcpc$data.clust$clust))\n\n\n# ------------------------------------------------------------\n# 6. Visualiser les classes sur le premier plan factoriel\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('5. Graphique ACP color'e par classe HCPC\\n')\ncat('============================================================\\n')\ncat('Le graphique repr'esente les individus sur le plan Dim.1 x Dim.2.\\n')\ncat('La couleur correspond `a la classe construite par HCPC.\\n')\n\nFactoMineR::plot.HCPC(res_hcpc, choice = 'map', draw.tree = FALSE)\n\n# ------------------------------------------------------------\n# 7. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e p'edagogique\\n')\ncat('============================================================\\n')\ncat('Nous avons cr'e'e une nouvelle variable : res_hcpc$data.clust$clust.\\n')\ncat('Cette variable n est pas une r'eponse directe du questionnaire.\\n')\ncat('Elle r'esulte d une ACP puis d une classification.\\n')\ncat('\\n')\ncat('La prochaine 'etape consiste `a d'ecrire statistiquement ces classes.\\n')",
                                           code_display = "# V'erifier les pr'erequis\n\nif (!exists('questionnaire')) {\nstop(\n'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\ncall. = FALSE\n)\n}\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\nstop(\n'Le package FactoMineR est n'ecessaire pour cette case.',\ncall. = FALSE\n)\n}\n\n# D'efinir les variables actives qui vont construire la typologie\n\nvariables_typologie <- c(\n'attention_prix',\n'contrainte_temps',\n'cuisine_maison',\n'lecture_labels',\n'achat_local',\n'ouverture_innovation',\n'usage_appli_alim',\n'preoccupation_sante',\n'autonomie_alimentaire',\n'confiance_labels'\n)\n\n# V'erifier que toutes les variables actives sont pr'esentes\n\nvariables_absentes <- setdiff(\nvariables_typologie,\nnames(questionnaire)\n)\n\nif (length(variables_absentes) > 0) {\nstop(\n'Variables de typologie absentes du questionnaire : ',\npaste(variables_absentes, collapse = ', '),\ncall. = FALSE\n)\n}\n\nvariables_typologie\n\n# Pr'eparer le tableau actif pour l ACP\n\ndonnees_typologie <- questionnaire[, variables_typologie]\n\n# V'erifier que les variables actives sont bien num'eriques\n\nvariables_non_numeriques <- names(donnees_typologie)[\n!vapply(donnees_typologie, is.numeric, logical(1))\n]\n\nif (length(variables_non_numeriques) > 0) {\nstop(\n'Les variables suivantes ne sont pas num'eriques : ',\npaste(variables_non_numeriques, collapse = ', '),\n'. Une ACP n'ecessite ici des variables quantitatives.',\ncall. = FALSE\n)\n}\n\ndim(donnees_typologie)\nhead(donnees_typologie, 3)\n\n# R'ealiser l ACP sur les variables actives\n\nres_pca <- FactoMineR::PCA(\ndonnees_typologie,\nscale.unit = TRUE,\ngraph = FALSE\n)\n\n# Examiner l inertie des premiers axes\n\nres_pca$eig\n\n# R'ealiser la classification HCPC `a partir de l ACP\n\nset.seed(123)\n\nres_hcpc <- FactoMineR::HCPC(\nres_pca,\nnb.clust = 3,\ngraph = FALSE\n)\n\n# Examiner la variable de classe construite\n\ntable(res_hcpc$data.clust$clust)\n\n# Visualiser les classes sur le premier plan factoriel\n\nFactoMineR::plot.HCPC(\nres_hcpc,\nchoice = 'map',\ndraw.tree = FALSE\n)",
                                           expected_output = "Une ACP `res_pca`, une classification `res_hcpc` et une variable `res_hcpc$data.clust$clust`.",
                                           transition = "On d'ecrit maintenant les classes construites avec catdes(), puis avec nail_catdes().",
                                           outputs = c("console", "plot"), question = "Quelle fonction de FactoMineR permet de construire une classification `a partir d'une ACP ?",
                                           expected_answer = "HCPC", validator = NULL, pdf = NULL,
                                           pdf_on_run = NULL, next_steps = "decrire_classes", prerequisites = character(0),
                                           concepts = character(0), layout = list(x = 260, y = 420)), class = "serious_step"),
         decrire_classes = structure(list(id = "decrire_classes",
                                          title = "Le Profilage", section = "stat", objective = "D'ecrire la variable de classe construite avec catdes() et nail_catdes().",
                                          text = NULL, code = "# ============================================================\n# Case 14 : d'ecrire les classes HCPC\n# ============================================================\n\n# Objectif de cette case :\n# interpr'eter une variable de classe construite.\n#\n# classe_hcpc n est pas une variable directement pos'ee aux r'epondants.\n# Elle doit donc ^etre d'ecrite, caract'eris'ee et nomm'ee avec prudence.\n#\n# On commence par FactoMineR::catdes(), puis on regarde comment\n# NaileR peut prolonger cette logique avec nail_catdes().\n\n# ------------------------------------------------------------\n# 1. V'erifier les pr'erequis\n# ------------------------------------------------------------\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\n    call. = FALSE\n  )\n}\n\n\nif (is.null(res_hcpc$data.clust) ||\n    !'clust' %in% names(res_hcpc$data.clust)) {\n  stop(\n    'res_hcpc existe, mais res_hcpc$data.clust$clust est absent.',\n    call. = FALSE\n  )\n}\n\nquestionnaire$classe_hcpc <- factor(res_hcpc$data.clust$clust)\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\n  stop(\n    'Le package FactoMineR est n'ecessaire pour cette case.',\n    call. = FALSE\n  )\n}\n\n\n# ------------------------------------------------------------\n# 2. Pr'eparer le tableau de description des classes\n# ------------------------------------------------------------\n\nquestionnaire_desc_classes <- questionnaire[\n  ,\n  setdiff(names(questionnaire), c('id', 'commentaire'))\n]\n\nnum_var_classe <- which(\n  names(questionnaire_desc_classes) == 'classe_hcpc'\n)\n\ncat('\\n============================================================\\n')\ncat('1. Variable de classe `a d'ecrire\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : questionnaire_desc_classes\\n')\ncat('Variable d'ecrite : classe_hcpc\\n')\ncat('Position de classe_hcpc : ', num_var_classe, '\\n', sep = '')\n\ncat('\\nR'epartition des classes :\\n')\nprint(table(questionnaire_desc_classes$classe_hcpc))\n\n\n# ------------------------------------------------------------\n# 3. D'ecrire les classes avec catdes()\n# ------------------------------------------------------------\n\nres_catdes_classes <- FactoMineR::catdes(\n  questionnaire_desc_classes,\n  num.var = num_var_classe\n)\n\ncat('\\n============================================================\\n')\ncat('2. Description des classes avec FactoMineR::catdes()\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_catdes_classes\\n')\n\ncat('\\n'El'ements contenus dans res_catdes_classes :\\n')\nprint(names(res_catdes_classes))\n\ncat('\\nApercu de la sortie catdes() :\\n')\ntexte_catdes_classes <- paste(\n  capture.output(print(res_catdes_classes)),\n  collapse = '\\n'\n)\n\ncat(substr(texte_catdes_classes, 1, 2500))\n\nif (nchar(texte_catdes_classes) > 2500) {\n  cat('\\n\\n[... sortie catdes tronqu'ee dans l affichage ...]\\n')\n  cat('Longueur totale : ', nchar(texte_catdes_classes), ' caract`eres\\n', sep = '')\n}\n\n\n# ------------------------------------------------------------\n# 4. Prolonger avec nail_catdes() si NaileR est disponible\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('3. Prolongement avec NaileR::nail_catdes()\\n')\ncat('============================================================\\n')\n\nif (!requireNamespace('NaileR', quietly = TRUE)) {\n\n  res_nail_catdes_classes <- 'NaileR n est pas install'e : nail_catdes() ne peut pas ^etre ex'ecut'e.'\n  cat(res_nail_catdes_classes, '\\n')\n\n} else {\n\n  res_nail_catdes_classes <- tryCatch(\n    NaileR::nail_catdes(\n      questionnaire_desc_classes,\n      num.var = num_var_classe,\n      generate = FALSE,\n      interpretation_mode = 'latent'\n    ),\n    error = function(e) {\n      paste('nail_catdes() non ex'ecut'e :', conditionMessage(e))\n    }\n  )\n\n  cat('Objet cr'e'e : res_nail_catdes_classes\\n')\n  cat('Classe : ', paste(class(res_nail_catdes_classes), collapse = ', '), '\\n', sep = '')\n\n  if (is.list(res_nail_catdes_classes)) {\n    cat('\\nNoms disponibles :\\n')\n    print(names(res_nail_catdes_classes))\n  }\n\n# ------------------------------------------------------------\n# Affichage lisible de la sortie nail_catdes()\n# ------------------------------------------------------------\n\nextraire_texte_lisible <- function(objet) {\n\n  if (is.list(objet)) {\n\n    champs_possibles <- c(\n      'prompt',\n      'request',\n      'response',\n      'interpretation',\n      'text',\n      'result'\n    )\n\n    champ_trouve <- intersect(champs_possibles, names(objet))\n\n    if (length(champ_trouve) > 0) {\n      texte <- objet[[champ_trouve[1]]]\n    } else {\n      texte <- capture.output(str(objet, max.level = 2))\n    }\n\n  } else {\n    texte <- capture.output(print(objet))\n  }\n\n  texte <- paste(texte, collapse = '\n')\n\n  # Transforme les retours `a la ligne 'echapp'es en vrais retours `a la ligne\n  texte <- gsub('\\\\n', '\n', texte)\n\n  # Transforme les tabulations 'echapp'ees si besoin\n  texte <- gsub('\\\\t', '\t', texte)\n\n  texte\n}\n\nafficher_apercu_lisible <- function(texte, n_lignes = 60, largeur = 100) {\n\n  lignes <- unlist(strsplit(texte, '\n', fixed = TRUE))\n\n  lignes_wrappees <- unlist(\n    lapply(lignes, function(ligne) {\n      if (!nzchar(trimws(ligne))) {\n        return('')\n      }\n      strwrap(ligne, width = largeur)\n    })\n  )\n\n  lignes_affichees <- head(lignes_wrappees, n_lignes)\n\n  cat(paste(lignes_affichees, collapse = '\n'))\n\n  if (length(lignes_wrappees) > n_lignes) {\n    cat('\n\n[... apercu tronqu'e ...]\n')\n    cat('Nombre total de lignes : ', length(lignes_wrappees), '\n', sep = '')\n  }\n}\n\ntexte_nail_catdes_classes <- extraire_texte_lisible(\n  res_nail_catdes_classes\n)\n\ncat('\nApercu lisible :\n\n')\n\nafficher_apercu_lisible(\n  texte = texte_nail_catdes_classes,\n  n_lignes = 60,\n  largeur = 100\n)\n}\n\n\n# ------------------------------------------------------------\n# 5. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e p'edagogique\\n')\ncat('============================================================\\n')\ncat('Une classe construite doit ^etre d'ecrite avant d ^etre nomm'ee.\\n')\ncat('catdes() donne les variables et modalit'es qui caract'erisent les classes.\\n')\ncat('nail_catdes() prolonge cette logique vers un prompt ou une interpr'etation contr^ol'ee.\\n')\ncat('\\n')\ncat('La prochaine 'etape ajoute les verbatims associ'es `a ces classes.\\n')",
                                          code_display = "# V'erifier les pr'erequis\n\nif (!exists('questionnaire')) {\nstop(\n'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\ncall. = FALSE\n)\n}\n\n\nif (!requireNamespace('FactoMineR', quietly = TRUE)) {\nstop(\n'Le package FactoMineR est n'ecessaire pour cette case.',\ncall. = FALSE\n)\n}\n\n# Ajouter au questionnaire la variable de classe construite par HCPC\n\nquestionnaire$classe_hcpc <- res_hcpc$data.clust$clust\n\n# Pr'eparer le tableau de description des classes\n\n# On retire l identifiant et le commentaire libre.\n\nquestionnaire_desc_classes <- questionnaire[\n,\nsetdiff(names(questionnaire), c('id', 'commentaire'))\n]\n\n# Rep'erer la position de la variable de classe\n\nnum_var_classe <- which(\nnames(questionnaire_desc_classes) == 'classe_hcpc'\n)\n\n# Examiner la r'epartition des classes\n\ntable(questionnaire_desc_classes$classe_hcpc)\n\n# D'ecrire les classes avec FactoMineR::catdes()\n\nres_catdes_classes <- FactoMineR::catdes(\nquestionnaire_desc_classes,\nnum.var = num_var_classe\n)\n\n# Examiner l objet retourn'e par catdes()\n\nnames(res_catdes_classes)\nres_catdes_classes\n\n# Capturer la sortie catdes() sous forme de texte\n\ntexte_catdes_classes <- paste(\ncapture.output(print(res_catdes_classes)),\ncollapse = '\n'\n)\n\nsubstr(texte_catdes_classes, 1, 2500)\nnchar(texte_catdes_classes)\n\n# Prolonger avec NaileR::nail_catdes() si NaileR est disponible\n\nif (!requireNamespace('NaileR', quietly = TRUE)) {\n\nres_nail_catdes_classes <- 'NaileR n est pas install'e : nail_catdes() ne peut pas ^etre ex'ecut'e.'\n\n} else {\n\nres_nail_catdes_classes <- tryCatch(\nNaileR::nail_catdes(\nquestionnaire_desc_classes,\nnum.var = num_var_classe,\ngenerate = FALSE,\ninterpretation_mode = 'latent'\n),\nerror = function(e) {\npaste('nail_catdes() non ex'ecut'e :', conditionMessage(e))\n}\n)\n}\n\n# Inspecter l objet retourn'e par nail_catdes()\n\nclass(res_nail_catdes_classes)\n\nif (is.list(res_nail_catdes_classes)) {\nnames(res_nail_catdes_classes)\n} else {\nres_nail_catdes_classes\n}\n\n# Extraire un champ textuel possible depuis l objet NaileR\n\nextraire_champ_possible <- function(objet, noms_possibles) {\n\nif (!is.list(objet)) {\nreturn(NULL)\n}\n\nnoms_objet <- names(objet)\n\nif (is.null(noms_objet)) {\nreturn(NULL)\n}\n\nfor (nom in noms_possibles) {\nif (nom %in% noms_objet) {\nreturn(objet[[nom]])\n}\n}\n\nNULL\n}\n\nprompt_nail_catdes_classes <- extraire_champ_possible(\nres_nail_catdes_classes,\nc(\n'prompt',\n'prompts',\n'request',\n'text_prompt',\n'text',\n'result'\n)\n)\n\n# Transformer le prompt 'eventuel en texte lisible\n\nif (!is.null(prompt_nail_catdes_classes)) {\n\nprompt_nail_catdes_classes <- paste(\nas.character(prompt_nail_catdes_classes),\ncollapse = '\n'\n)\n\nprompt_nail_catdes_classes <- gsub(\n'\\n',\n'\n',\nprompt_nail_catdes_classes\n)\n\nsubstr(prompt_nail_catdes_classes, 1, 2000)\nnchar(prompt_nail_catdes_classes)\n}",
                                          expected_output = "Une description statistique `res_catdes_classes` et, si NaileR est disponible, un objet `res_nail_catdes_classes`.",
                                          transition = "On pr'epare maintenant les verbatims associ'es aux classes construites.",
                                          outputs = "console", question = "Quel est le nom de la variable de classe ajout'ee au questionnaire ?",
                                          expected_answer = "classe_hcpc", validator = NULL, pdf = NULL,
                                          pdf_on_run = NULL, next_steps = "preparer_textes_classes",
                                          prerequisites = character(0), concepts = character(0),
                                          layout = list(x = 520, y = 420)), class = "serious_step"),
         preparer_textes_classes = structure(list(id = "preparer_textes_classes",
                                                  title = "Le Pont Textuel", section = "r_sorties", objective = "Pr'eparer le tableau qui permettra `a NaileR de croiser classes, commentaires libres et variables du questionnaire.",
                                                  text = NULL, code = "# ============================================================\n# Case 15 : pr'eparer les verbatims par classe\n# ============================================================\n\n# Objectif de cette case :\n# relier la variable de classe construite aux commentaires libres.\n#\n# La classe_hcpc donne une structure latente.\n# La variable commentaire apporte des verbatims.\n#\n# On pr'epare donc un tableau qui associe :\n# - une classe construite ;\n# - un texte libre ;\n# - des variables structur'ees utiles pour contextualiser l interpr'etation.\n\n# ------------------------------------------------------------\n# 1. V'erifier les pr'erequis\n# ------------------------------------------------------------\n\nif (!exists('questionnaire')) {\n  stop(\n    'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\n    call. = FALSE\n  )\n}\n\nvariables_requises <- c('classe_hcpc', 'commentaire')\n\nvariables_absentes <- setdiff(\n  variables_requises,\n  names(questionnaire)\n)\n\nif (length(variables_absentes) > 0) {\n  stop(\n    'Variables absentes : ',\n    paste(variables_absentes, collapse = ', '),\n    '. Ex'ecute d abord les cases pr'ec'edentes.',\n    call. = FALSE\n  )\n}\n\n\n# ------------------------------------------------------------\n# 2. Construire le tableau textuel latent\n# ------------------------------------------------------------\n\nvariables_textuelles_classes <- c(\n  'classe_hcpc',\n  'commentaire',\n  'satisfaction',\n  'intention_achat',\n  'prix_percu',\n  'plaisir',\n  'naturalite',\n  'confiance',\n  'ancrage_local',\n  'usage_numerique',\n  'sensibilite_env',\n  'attention_prix',\n  'contrainte_temps',\n  'cuisine_maison',\n  'lecture_labels',\n  'achat_local',\n  'ouverture_innovation',\n  'usage_appli_alim',\n  'preoccupation_sante',\n  'autonomie_alimentaire',\n  'confiance_labels',\n  'type_produit',\n  'budget_contraint',\n  'sexe',\n  'age_classe',\n  'lieu_achat',\n  'profil_alim'\n)\n\nvariables_textuelles_classes <- intersect(\n  variables_textuelles_classes,\n  names(questionnaire)\n)\n\ndataset_textuel_classes <- questionnaire[, variables_textuelles_classes]\n\ndataset_textuel_classes$classe_hcpc <- factor(dataset_textuel_classes$classe_hcpc)\ndataset_textuel_classes$commentaire <- as.character(dataset_textuel_classes$commentaire)\n\ncat('\\n============================================================\\n')\ncat('1. Tableau textuel par classe cr'e'e\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : dataset_textuel_classes\\n')\ncat('Variable de groupe : classe_hcpc\\n')\ncat('Variable textuelle : commentaire\\n')\ncat('Nombre de lignes : ', nrow(dataset_textuel_classes), '\\n', sep = '')\ncat('Nombre de colonnes : ', ncol(dataset_textuel_classes), '\\n', sep = '')\n\ncat('\\nVariables conserv'ees :\\n')\nprint(names(dataset_textuel_classes))\n\n\n# ------------------------------------------------------------\n# 3. Examiner la r'epartition des classes\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('2. R'epartition des classes\\n')\ncat('============================================================\\n')\nprint(table(dataset_textuel_classes$classe_hcpc))\n\n\n# ------------------------------------------------------------\n# 4. Examiner les verbatims\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('3. Apercu des commentaires libres\\n')\ncat('============================================================\\n')\ncat('Nombre total de verbatims : ', length(dataset_textuel_classes$commentaire), '\\n', sep = '')\ncat('Nombre de verbatims uniques : ', length(unique(dataset_textuel_classes$commentaire)), '\\n', sep = '')\n\ncat('\\nExemples de verbatims :\\n')\ncat(paste('-', head(unique(dataset_textuel_classes$commentaire), 8), collapse = '\\n'))\ncat('\\n')\n\n\n# ------------------------------------------------------------\n# 5. Verbatims par classe\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('4. Exemples de verbatims par classe\\n')\ncat('============================================================\\n')\n\nfor (cl in levels(dataset_textuel_classes$classe_hcpc)) {\n  cat('\\n--- Classe ', cl, ' ---\\n', sep = '')\n\n  verbatims_classe <- unique(\n    dataset_textuel_classes$commentaire[\n      dataset_textuel_classes$classe_hcpc == cl\n    ]\n  )\n\n  cat(paste('-', head(verbatims_classe, 4), collapse = '\\n'))\n  cat('\\n')\n}\n\n\n# ------------------------------------------------------------\n# 6. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e p'edagogique\\n')\ncat('============================================================\\n')\ncat('Cette case ne produit pas une nouvelle analyse statistique.\n')\ncat('Elle pr'epare le format de donn'ees n'ecessaire pour passer de catdes() aux fonctions textuelles de NaileR.\n')\ncat('On conserve une ligne par r'epondant afin de garder le lien entre classe, commentaire et variables structur'ees.\n')",
                                                  code_display = "# V'erifier les pr'erequis\n\nif (!exists('questionnaire')) {\nstop(\n'L objet questionnaire est absent. Ex'ecute d abord la case 1.',\ncall. = FALSE\n)\n}\n\nvariables_requises <- c(\n'classe_hcpc',\n'commentaire'\n)\n\nvariables_absentes <- setdiff(\nvariables_requises,\nnames(questionnaire)\n)\n\nif (length(variables_absentes) > 0) {\nstop(\n'Variables absentes : ',\npaste(variables_absentes, collapse = ', '),\n'. Ex'ecute d abord les cases pr'ec'edentes.',\ncall. = FALSE\n)\n}\n\n# D'efinir les variables `a conserver pour relier classes et verbatims\n\nvariables_textuelles_classes <- c(\n'classe_hcpc',\n'commentaire',\n'satisfaction',\n'intention_achat',\n'prix_percu',\n'plaisir',\n'naturalite',\n'confiance',\n'ancrage_local',\n'usage_numerique',\n'sensibilite_env',\n'attention_prix',\n'contrainte_temps',\n'cuisine_maison',\n'lecture_labels',\n'achat_local',\n'ouverture_innovation',\n'usage_appli_alim',\n'preoccupation_sante',\n'autonomie_alimentaire',\n'confiance_labels',\n'type_produit',\n'budget_contraint',\n'sexe',\n'age_classe',\n'lieu_achat',\n'profil_alim'\n)\n\nvariables_textuelles_classes <- intersect(\nvariables_textuelles_classes,\nnames(questionnaire)\n)\n\n# Construire le tableau textuel par classe\n\ndataset_textuel_classes <- questionnaire[\n,\nvariables_textuelles_classes\n]\n\n# S'ecuriser les types des deux variables centrales\n\ndataset_textuel_classes$classe_hcpc <- factor(\ndataset_textuel_classes$classe_hcpc\n)\n\ndataset_textuel_classes$commentaire <- as.character(\ndataset_textuel_classes$commentaire\n)\n\n# Examiner le tableau cr'e'e\n\ndim(dataset_textuel_classes)\nnames(dataset_textuel_classes)\n\n# Examiner la r'epartition des classes\n\ntable(dataset_textuel_classes$classe_hcpc)\n\n# Examiner les commentaires libres\n\nlength(dataset_textuel_classes$commentaire)\nlength(unique(dataset_textuel_classes$commentaire))\n\nhead(\nunique(dataset_textuel_classes$commentaire),\n8\n)\n\n# Pr'eparer les verbatims par classe\n\nverbatims_par_classe <- split(\ndataset_textuel_classes$commentaire,\ndataset_textuel_classes$classe_hcpc\n)\n\nverbatims_par_classe <- lapply(\nverbatims_par_classe,\nunique\n)\n\n# Afficher quelques verbatims par classe\n\nlapply(\nverbatims_par_classe,\nhead,\n4\n)",
                                                  expected_output = "Un tableau `dataset_textuel_classes` associant `classe_hcpc`, `commentaire` et les variables structur'ees.",
                                                  transition = "On pr'epare maintenant deux artefacts : un profil textuel et un profil structur'e des classes.",
                                                  outputs = "console", question = "Quelle variable construite sert `a regrouper les commentaires libres ?",
                                                  expected_answer = "classe_hcpc", validator = NULL, pdf = NULL,
                                                  pdf_on_run = NULL, next_steps = "preparer_artefacts_classes",
                                                  prerequisites = character(0), concepts = character(0),
                                                  layout = list(x = 780, y = 420)), class = "serious_step"),
         preparer_artefacts_classes = structure(list(id = "preparer_artefacts_classes",
                                                     title = "La Fabrique d'Artefacts", section = "entrainer",
                                                     objective = "Pr'eparer les artefacts textuels et structur'es des classes avec NaileR.",
                                                     text = NULL, code = "# ============================================================\n# Case 16 : pr'eparer les artefacts textuels et structur'es\n# ============================================================\n\n# Objectif de cette case :\n# pr'eparer deux types d artefacts pour interpr'eter les classes :\n#\n# 1. un artefact textuel issu des verbatims ;\n# 2. un artefact structur'e issu des variables du questionnaire.\n#\n# Ces artefacts sont inspectables et pourront ^etre combin'es\n# dans une synth`ese contextualis'ee.\n\n# ------------------------------------------------------------\n# 1. V'erifier les pr'erequis\n# ------------------------------------------------------------\n\nif (!exists('dataset_textuel_classes')) {\n  stop(\n    'L objet dataset_textuel_classes est absent. Ex'ecute d abord la case 15.',\n    call. = FALSE\n  )\n}\n\nif (!requireNamespace('NaileR', quietly = TRUE)) {\n  res_textual_prep_classes <- 'NaileR n est pas install'e : nail_textual_prep() ne peut pas ^etre ex'ecut'e.'\n  res_group_profile_classes <- 'NaileR n est pas install'e : nail_group_profile_prep() ne peut pas ^etre ex'ecut'e.'\n\n  cat('\\n============================================================\\n')\n  cat('NaileR indisponible\\n')\n  cat('============================================================\\n')\n  cat('Les artefacts NaileR ne peuvent pas ^etre produits sur cette machine.\\n')\n\n} else {\n\n# ----------------------------------------------------------\n# Fonction utilitaire : afficher proprement un objet NaileR\n# ----------------------------------------------------------\n\nextraire_texte_lisible <- function(objet) {\n\n  if (is.list(objet)) {\n\n    champs_possibles <- c(\n      'prompt',\n      'prompts',\n      'request',\n      'response',\n      'text',\n      'texts',\n      'interpretation',\n      'summary',\n      'profile'\n    )\n\n    champs_trouves <- intersect(champs_possibles, names(objet))\n\n    if (length(champs_trouves) > 0) {\n      texte <- objet[[champs_trouves[1]]]\n    } else {\n      texte <- capture.output(str(objet, max.level = 2))\n    }\n\n  } else {\n    texte <- objet\n  }\n\n  texte <- paste(as.character(texte), collapse = '\n')\n\n  # Convertir les retours `a la ligne 'echapp'es en vrais retours `a la ligne\n  texte <- gsub('\\\\n', '\n', texte)\n  texte <- gsub('\\\\t', '\t', texte)\n\n  texte\n}\n\nafficher_apercu_lisible <- function(texte, n_lignes = 70, largeur = 100) {\n\n  lignes <- unlist(strsplit(texte, '\n', fixed = TRUE))\n\n  lignes_wrappees <- unlist(\n    lapply(lignes, function(ligne) {\n      if (!nzchar(trimws(ligne))) {\n        return('')\n      }\n      strwrap(ligne, width = largeur)\n    })\n  )\n\n  lignes_affichees <- head(lignes_wrappees, n_lignes)\n\n  cat(paste(lignes_affichees, collapse = '\n'))\n\n  if (length(lignes_wrappees) > n_lignes) {\n    cat('\n\n[... apercu tronqu'e ...]\n')\n    cat('Nombre total de lignes : ', length(lignes_wrappees), '\n', sep = '')\n  }\n}\n\n\n  # ----------------------------------------------------------\n  # 2. Identifier les colonnes pour le profil textuel\n  # ----------------------------------------------------------\n\n  num_var_classes <- which(names(dataset_textuel_classes) == 'classe_hcpc')\n  num_text_classes <- which(names(dataset_textuel_classes) == 'commentaire')\n\n  cat('\\n============================================================\\n')\n  cat('1. Colonnes utilis'ees par les fonctions textuelles\\n')\n  cat('============================================================\\n')\n  cat('num.var  = ', num_var_classes, '  # classe_hcpc\\n', sep = '')\n  cat('num.text = ', num_text_classes, '  # commentaire\\n', sep = '')\n\n\n  # ----------------------------------------------------------\n  # 3. Pr'eparer l artefact textuel\n  # ----------------------------------------------------------\n\n  cat('\\n============================================================\\n')\n  cat('2. Pr'eparation de l artefact textuel\\n')\n  cat('============================================================\\n')\n  cat('Fonction : NaileR::nail_textual_prep()\\n')\n  cat('generate = FALSE : pr'eparation sans g'en'eration LLM.\\n')\n\n  res_textual_prep_classes <- tryCatch(\n    NaileR::nail_textual_prep(\n      dataset = dataset_textuel_classes,\n      num.var = num_var_classes,\n      num.text = num_text_classes,\n      model = 'llama3',\n      generate = FALSE\n    ),\n    error = function(e) {\n      paste('nail_textual_prep() non ex'ecut'e :', conditionMessage(e))\n    }\n  )\n\n  cat('\\nObjet cr'e'e : res_textual_prep_classes\\n')\n  cat('Classe : ', paste(class(res_textual_prep_classes), collapse = ', '), '\\n', sep = '')\n\n  if (is.list(res_textual_prep_classes)) {\n    cat('\\nNoms disponibles :\\n')\n    print(names(res_textual_prep_classes))\n\n   texte_premier_artefact <- extraire_texte_lisible(\n  res_textual_prep_classes[[1]]\n)\n\ncat('\nApercu lisible du premier artefact textuel :\n\n')\n\nafficher_apercu_lisible(\n  texte = texte_premier_artefact,\n  n_lignes = 70,\n  largeur = 100\n)\n  } else {\n    cat('\\nMessage ou sortie :\\n')\n    cat(as.character(res_textual_prep_classes), '\\n')\n  }\n\n\n  # ----------------------------------------------------------\n  # 4. Pr'eparer l artefact structur'e\n  # ----------------------------------------------------------\n\n  dataset_profil_classes <- dataset_textuel_classes[\n    ,\n    setdiff(names(dataset_textuel_classes), 'commentaire')\n  ]\n\n  num_var_profil_classes <- which(\n    names(dataset_profil_classes) == 'classe_hcpc'\n  )\n\n  cat('\\n============================================================\\n')\n  cat('3. Pr'eparation de l artefact structur'e\\n')\n  cat('============================================================\\n')\n  cat('Objet cr'e'e : dataset_profil_classes\\n')\n  cat('Fonction : NaileR::nail_group_profile_prep()\\n')\n  cat('generate = FALSE : pr'eparation sans g'en'eration LLM.\\n')\n\n  res_group_profile_classes <- tryCatch(\n    NaileR::nail_group_profile_prep(\n      dataset = dataset_profil_classes,\n      num.var = num_var_profil_classes,\n      model = 'llama3',\n      generate = FALSE\n    ),\n    error = function(e) {\n      paste('nail_group_profile_prep() non ex'ecut'e :', conditionMessage(e))\n    }\n  )\n\n  cat('\\nObjet cr'e'e : res_group_profile_classes\\n')\n  cat('Classe : ', paste(class(res_group_profile_classes), collapse = ', '), '\\n', sep = '')\n\n  if (is.list(res_group_profile_classes)) {\n    cat('\\nNoms disponibles :\\n')\n    print(names(res_group_profile_classes))\n\n    texte_premier_profil <- extraire_texte_lisible(\n  res_group_profile_classes[[1]]\n)\n\ncat('\nApercu lisible du premier artefact structur'e :\n\n')\n\nafficher_apercu_lisible(\n  texte = texte_premier_profil,\n  n_lignes = 70,\n  largeur = 100\n)\n  } else {\n    cat('\\nMessage ou sortie :\\n')\n    cat(as.character(res_group_profile_classes), '\\n')\n  }\n}\n\n\n# ------------------------------------------------------------\n# 5. Comparaison p'edagogique\n# ------------------------------------------------------------\n\ncomparaison_artefacts_classes <- data.frame(\n  fonction = c(\n    'nail_textual_prep()',\n    'nail_group_profile_prep()'\n  ),\n  materiau = c(\n    'commentaires libres',\n    'variables structur'ees du questionnaire'\n  ),\n  objet_cree = c(\n    'res_textual_prep_classes',\n    'res_group_profile_classes'\n  ),\n  role = c(\n    'pr'eparer un profil textuel par classe',\n    'pr'eparer un profil statistique ou descriptif par classe'\n  ),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('4. Deux artefacts compl'ementaires\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : comparaison_artefacts_classes\\n')\nprint(comparaison_artefacts_classes, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 6. R'esum'e p'edagogique\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('R'esum'e p'edagogique\\n')\ncat('============================================================\\n')\ncat('On dispose maintenant de deux objets compl'ementaires :\\n')\ncat('- res_textual_prep_classes : ce que disent les verbatims ;\\n')\ncat('- res_group_profile_classes : ce que disent les variables structur'ees.\\n')\ncat('\\n')\ncat('La derni`ere case combine ces deux sources.\\n')",
                                                     code_display = "# V'erifier que le tableau textuel par classe existe\n\nif (!exists('dataset_textuel_classes')) {\nstop(\n'L objet dataset_textuel_classes est absent. Ex'ecute d abord la case 15.',\ncall. = FALSE\n)\n}\n\n# V'erifier que NaileR est disponible\n\nif (!requireNamespace('NaileR', quietly = TRUE)) {\n\nres_textual_prep_classes <- 'NaileR n est pas install'e : nail_textual_prep() ne peut pas ^etre ex'ecut'e.'\nres_group_profile_classes <- 'NaileR n est pas install'e : nail_group_profile_prep() ne peut pas ^etre ex'ecut'e.'\n\n} else {\n\n# Identifier la variable de classe et la variable textuelle\n\nnum_var_classes <- which(\nnames(dataset_textuel_classes) == 'classe_hcpc'\n)\n\nnum_text_classes <- which(\nnames(dataset_textuel_classes) == 'commentaire'\n)\n\nnum_var_classes\nnum_text_classes\n\n# Pr'eparer l artefact textuel `a partir des verbatims\n\nres_textual_prep_classes <- tryCatch(\nNaileR::nail_textual_prep(\ndataset = dataset_textuel_classes,\nnum.var = num_var_classes,\nnum.text = num_text_classes,\nmodel = 'llama3',\ngenerate = FALSE\n),\nerror = function(e) {\npaste(\n'nail_textual_prep() non ex'ecut'e :',\nconditionMessage(e)\n)\n}\n)\n\n# Inspecter l artefact textuel\n\nclass(res_textual_prep_classes)\n\nif (is.list(res_textual_prep_classes)) {\nnames(res_textual_prep_classes)\nstr(res_textual_prep_classes[[1]], max.level = 2)\n} else {\nres_textual_prep_classes\n}\n\n# Pr'eparer le tableau structur'e :\n\n# m^eme tableau, mais sans la colonne de commentaires libres.\n\ndataset_profil_classes <- dataset_textuel_classes[\n,\nsetdiff(names(dataset_textuel_classes), 'commentaire')\n]\n\nnum_var_profil_classes <- which(\nnames(dataset_profil_classes) == 'classe_hcpc'\n)\n\nnames(dataset_profil_classes)\nnum_var_profil_classes\n\n# Pr'eparer l artefact structur'e `a partir des variables du questionnaire\n\nres_group_profile_classes <- tryCatch(\nNaileR::nail_group_profile_prep(\ndataset = dataset_profil_classes,\nnum.var = num_var_profil_classes,\nmodel = 'llama3',\ngenerate = FALSE\n),\nerror = function(e) {\npaste(\n'nail_group_profile_prep() non ex'ecut'e :',\nconditionMessage(e)\n)\n}\n)\n\n# Inspecter l artefact structur'e\n\nclass(res_group_profile_classes)\n\nif (is.list(res_group_profile_classes)) {\nnames(res_group_profile_classes)\nstr(res_group_profile_classes[[1]], max.level = 2)\n} else {\nres_group_profile_classes\n}\n}\n\n# Comparer les deux artefacts pr'epar'es\n\ncomparaison_artefacts_classes <- data.frame(\nfonction = c(\n'nail_textual_prep()',\n'nail_group_profile_prep()'\n),\nmateriau = c(\n'commentaires libres',\n'variables structur'ees du questionnaire'\n),\nobjet_cree = c(\n'res_textual_prep_classes',\n'res_group_profile_classes'\n),\nrole = c(\n'pr'eparer un profil textuel par classe',\n'pr'eparer un profil statistique ou descriptif par classe'\n),\nstringsAsFactors = FALSE\n)\n\ncomparaison_artefacts_classes",
                                                     expected_output = "Deux artefacts : `res_textual_prep_classes` et `res_group_profile_classes`.",
                                                     transition = "On combine maintenant les artefacts textuels et structur'es dans une synth`ese contextualis'ee.",
                                                     outputs = "console", question = "Quelle fonction de NaileR pr'epare les commentaires libres par classe ?",
                                                     expected_answer = "nail_textual_prep", validator = NULL,
                                                     pdf = NULL, pdf_on_run = NULL, next_steps = "synthese_contextualisee_classes",
                                                     prerequisites = character(0), concepts = character(0),
                                                     layout = list(x = 1040, y = 420)), class = "serious_step"),
         synthese_contextualisee_classes = structure(list(id = "synthese_contextualisee_classes",
                                                          title = "La Grande Synth`ese", section = "entrainer",
                                                          objective = "Combiner artefact textuel et artefact structur'e pour interpr'eter les classes.",
                                                          text = NULL, code = "# ============================================================\n# Case 17 : synth`ese contextualis'ee des classes\n# ============================================================\n\n# Objectif de cette case :\n# combiner deux sources pr'epar'ees :\n# - les verbatims ;\n# - les variables structur'ees.\n#\n# L id'ee centrale est un workflow centr'e sur les artefacts :\n# on ne demande pas au LLM d interpr'eter directement des textes bruts.\n# On lui donne des objets interm'ediaires pr'epar'es et inspectables.\n#\n# Dans cette version du tutoriel, la g'en'eration LLM n est pas faite\n# en direct. Si un r'esultat pr'e-calcul'e est disponible dans le package,\n# il est charg'e pour illustrer le r'esultat final.\n\n\n# ------------------------------------------------------------\n# 2. Fonctions utilitaires d affichage lisible\n# ------------------------------------------------------------\n\ntrouver_champ_texte <- function(objet, champs, profondeur = 0) {\n\n  if (profondeur > 3) {\n    return(NULL)\n  }\n\n  if (is.list(objet)) {\n\n    noms <- names(objet)\n\n    if (!is.null(noms)) {\n      champ_direct <- intersect(champs, noms)\n\n      if (length(champ_direct) > 0) {\n        return(objet[[champ_direct[1]]])\n      }\n    }\n\n    for (element in objet) {\n      resultat <- trouver_champ_texte(\n        element,\n        champs = champs,\n        profondeur = profondeur + 1\n      )\n\n      if (!is.null(resultat)) {\n        return(resultat)\n      }\n    }\n  }\n\n  NULL\n}\n\nextraire_champ_texte <- function(objet, champs) {\n\n  champ <- trouver_champ_texte(\n    objet = objet,\n    champs = champs\n  )\n\n  if (is.null(champ)) {\n    texte <- paste(\n      capture.output(str(objet, max.level = 2)),\n      collapse = '\\n'\n    )\n  } else {\n    texte <- paste(\n      as.character(champ),\n      collapse = '\\n'\n    )\n  }\n\n  # Conversion des retours `a la ligne 'echapp'es en vrais retours `a la ligne\n  texte <- gsub(\n    paste0(intToUtf8(92), 'n'),\n    '\\n',\n    texte,\n    fixed = TRUE\n  )\n\n  texte <- gsub(\n    paste0(intToUtf8(92), 't'),\n    '\\t',\n    texte,\n    fixed = TRUE\n  )\n\n  texte\n}\n\nafficher_texte_lisible <- function(texte, n_lignes = 90, largeur = 100) {\n\n  lignes <- unlist(\n    strsplit(\n      texte,\n      '\\n',\n      fixed = TRUE\n    )\n  )\n\n  lignes_wrappees <- unlist(\n    lapply(\n      lignes,\n      function(ligne) {\n        if (!nzchar(trimws(ligne))) {\n          return('')\n        }\n\n        strwrap(\n          ligne,\n          width = largeur\n        )\n      }\n    )\n  )\n\n  lignes_affichees <- head(\n    lignes_wrappees,\n    n_lignes\n  )\n\n  cat(\n    paste(\n      lignes_affichees,\n      collapse = '\\n'\n    )\n  )\n\n  if (length(lignes_wrappees) > n_lignes) {\n    cat('\\n\\n[... sortie tronqu'ee ...]\\n')\n    cat(\n      'Nombre total de lignes : ',\n      length(lignes_wrappees),\n      '\\n',\n      sep = ''\n    )\n  }\n}\n\n\n# ------------------------------------------------------------\n# 3. Chercher une g'en'eration pr'e-calcul'ee\n# ------------------------------------------------------------\n\nprecomputed_error <- NULL\n\nprecomputed_case17 <- tryCatch(\n  load_precomputed_asset('case17_nailer_contextualized.rds'),\n  error = function(e) {\n    precomputed_error <<- conditionMessage(e)\n    NULL\n  }\n)\n\ngeneration_precalculee <- !is.null(precomputed_case17)\n\nif (generation_precalculee) {\n\n  res_textual_prep_classes <- precomputed_case17$res_textual_prep_classes\n  res_group_profile_classes <- precomputed_case17$res_group_profile_classes\n  res_contextualized_classes <- precomputed_case17$res_contextualized_classes\n\n  cat('\\n============================================================\\n')\n  cat('1. G'en'eration pr'e-calcul'ee charg'ee\\n')\n  cat('============================================================\\n')\n  cat('La g'en'eration LLM n est pas r'ealis'ee en direct.\\n')\n  cat('Un r'esultat pr'e-calcul'e est charg'e depuis le package.\\n\\n')\n\n  if (!is.null(precomputed_case17$metadata)) {\n    cat('M'etadonn'ees :\\n')\n    print(precomputed_case17$metadata)\n  }\n\n} else {\n\n  cat('\\n============================================================\\n')\n  cat('1. Aucun r'esultat pr'e-calcul'e trouv'e\\n')\n  cat('============================================================\\n')\n  cat('On pr'epare uniquement la structure avec generate = FALSE.\\n')\n\n  if (!is.null(precomputed_error)) {\n  cat('\nDiagnostic de recherche du fichier pr'e-calcul'e :\n')\n  cat(precomputed_error)\n  cat('\n')\n}\n\n  # ----------------------------------------------------------\n  # V'erifier les pr'erequis seulement si aucun pr'e-calcul\n  # n est disponible.\n  # ----------------------------------------------------------\n\n  if (!exists('res_textual_prep_classes')) {\n    stop(\n      'L objet res_textual_prep_classes est absent. Ex'ecute d abord la case 16.',\n      call. = FALSE\n    )\n  }\n\n  if (!exists('res_group_profile_classes')) {\n    stop(\n      'L objet res_group_profile_classes est absent. Ex'ecute d abord la case 16.',\n      call. = FALSE\n    )\n  }\n\n  if (!requireNamespace('NaileR', quietly = TRUE)) {\n    stop(\n      'NaileR est n'ecessaire si aucun r'esultat pr'e-calcul'e n est disponible.',\n      call. = FALSE\n    )\n  }\n\n  if (!is.list(res_textual_prep_classes) ||\n      !is.list(res_group_profile_classes)) {\n    stop(\n      'Les artefacts attendus ne sont pas disponibles sous forme de listes. ',\n      'V'erifie que la case 16 a bien 'et'e ex'ecut'ee avec NaileR install'e.',\n      call. = FALSE\n    )\n  }\n\n  res_contextualized_classes <- tryCatch(\n    NaileR::nail_textual_contextualized(\n      group_profile_prep = res_group_profile_classes,\n      textual_prep = res_textual_prep_classes,\n      interpretation_mode = 'comparative',\n      model = 'llama3',\n      generate = FALSE\n    ),\n    error = function(e) {\n      paste(\n        'nail_textual_contextualized() non ex'ecut'e :',\n        conditionMessage(e)\n      )\n    }\n  )\n}\n\n\n# ------------------------------------------------------------\n# 4. Artefacts disponibles\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('2. Artefacts disponibles\\n')\ncat('============================================================\\n')\ncat('Artefact textuel : res_textual_prep_classes\\n')\ncat('Artefact structur'e : res_group_profile_classes\\n')\ncat('Synth`ese contextualis'ee : res_contextualized_classes\\n')\n\n\n# ------------------------------------------------------------\n# 5. Pr'esenter le principe de contextualisation\n# ------------------------------------------------------------\n\nflow_contextualisation_classes <- data.frame(\n  source = c(\n    'Verbatims',\n    'Variables structur'ees',\n    'Synth`ese contextualis'ee'\n  ),\n  objet_R = c(\n    'res_textual_prep_classes',\n    'res_group_profile_classes',\n    'res_contextualized_classes'\n  ),\n  role = c(\n    'faire 'emerger les th`emes et formulations associ'es aux classes',\n    'd'ecrire les classes `a partir des variables du questionnaire',\n    'combiner les deux sources pour interpr'eter les classes'\n  ),\n  stringsAsFactors = FALSE\n)\n\ncat('\\n============================================================\\n')\ncat('3. Principe de contextualisation\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : flow_contextualisation_classes\\n')\nprint(flow_contextualisation_classes, row.names = FALSE)\n\n\n# ------------------------------------------------------------\n# 6. Inspecter la sortie contextualis'ee\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('4. Sortie contextualis'ee\\n')\ncat('============================================================\\n')\ncat('Objet cr'e'e : res_contextualized_classes\\n')\ncat(\n  'Classe : ',\n  paste(class(res_contextualized_classes), collapse = ', '),\n  '\\n',\n  sep = ''\n)\n\ncat('\\nMode de production : ')\nif (generation_precalculee) {\n  cat('r'esultat pr'e-calcul'e charg'e depuis le package\\n')\n} else {\n  cat('pr'eparation locale avec generate = FALSE\\n')\n}\n\n\n# ------------------------------------------------------------\n# 7. Afficher le prompt ou l objet pr'epar'e\n# ------------------------------------------------------------\n\ncat('\\n============================================================\\n')\ncat('5. Prompt ou objet pr'epar'e\\n')\ncat('============================================================\\n')\n\ntexte_prompt_contextualized <- extraire_champ_texte(\n  res_contextualized_classes,\n  champs = c(\n    'prompt',\n    'prompts',\n    'request',\n    'instruction',\n    'instructions'\n  )\n)\n\nafficher_texte_lisible(\n  texte = texte_prompt_contextualized,\n  n_lignes = 90,\n  largeur = 100\n)\n\n\n# ------------------------------------------------------------\n# 8. Afficher la r'eponse pr'e-calcul'ee si elle existe\n# ------------------------------------------------------------\n\ncat('\\n\\n============================================================\\n')\ncat('6. R'eponse ou interpr'etation g'en'er'ee\\n')\ncat('============================================================\\n')\n\ntexte_reponse_contextualized <- extraire_champ_texte(\n  res_contextualized_classes,\n  champs = c(\n    'response',\n    'answer',\n    'result',\n    'interpretation',\n    'summary',\n    'text'\n  )\n)\n\nafficher_texte_lisible(\n  texte = texte_reponse_contextualized,\n  n_lignes = 120,\n  largeur = 100\n)\n\n\n# ------------------------------------------------------------\n# 9. R'esum'e p'edagogique final\n# ------------------------------------------------------------\n\ncat('\\n\\n============================================================\\n')\ncat('R'esum'e p'edagogique\\n')\ncat('============================================================\\n')\ncat('Nous avons construit une variable de classe latente : classe_hcpc.\\n')\ncat('Nous l avons d'ecrite statistiquement avec catdes().\\n')\ncat('Nous avons ensuite pr'epar'e deux artefacts :\\n')\ncat('- un artefact textuel issu des commentaires ;\\n')\ncat('- un artefact structur'e issu des variables du questionnaire.\\n')\ncat('\\n')\ncat('La synth`ese contextualis'ee combine ces deux sources.\\n')\ncat('Dans le tutoriel, la g'en'eration peut ^etre pr'e-calcul'ee afin d 'eviter\\n')\ncat('un appel LLM en direct pendant la s'eance.\\n')\ncat('\\n')\ncat('C est le principe central du workflow : stabiliser l interpr'etation\\n')\ncat('par des objets interm'ediaires visibles et inspectables.\\n')",
                                                          code_display = "# Chercher une g'en'eration pr'e-calcul'ee\n\nprecomputed_error <- NULL\n\nprecomputed_case17 <- tryCatch(\nload_precomputed_asset('case17_nailer_contextualized.rds'),\nerror = function(e) {\nprecomputed_error <<- conditionMessage(e)\nNULL\n}\n)\n\ngeneration_precalculee <- !is.null(precomputed_case17)\n\nif (generation_precalculee) {\n  champs_requis_precomputed <- c(\n    'res_textual_prep_classes',\n    'res_group_profile_classes',\n    'res_contextualized_classes'\n  )\n\n  champs_absents_precomputed <- setdiff(\n    champs_requis_precomputed,\n    names(precomputed_case17)\n  )\n\n  if (length(champs_absents_precomputed) > 0) {\n    precomputed_error <- paste(\n      'Le fichier pr'e-calcul'e existe, mais il ne contient pas :',\n      paste(champs_absents_precomputed, collapse = ', ')\n    )\n\n    precomputed_case17 <- NULL\n    generation_precalculee <- FALSE\n  }\n}\n\n# Si le r'esultat pr'e-calcul'e existe, on le charge.\n\n# Sinon, on reconstruit seulement la structure avec generate = FALSE.\n\nif (generation_precalculee) {\n\nres_textual_prep_classes <- precomputed_case17$res_textual_prep_classes\nres_group_profile_classes <- precomputed_case17$res_group_profile_classes\nres_contextualized_classes <- precomputed_case17$res_contextualized_classes\n\nprecomputed_case17$metadata\n\n} else {\n\nprecomputed_error\n\nif (!exists('res_textual_prep_classes')) {\nstop(\n'L objet res_textual_prep_classes est absent. Ex'ecute d abord la case 16.',\ncall. = FALSE\n)\n}\n\nif (!exists('res_group_profile_classes')) {\nstop(\n'L objet res_group_profile_classes est absent. Ex'ecute d abord la case 16.',\ncall. = FALSE\n)\n}\n\nif (!requireNamespace('NaileR', quietly = TRUE)) {\nstop(\n'NaileR est n'ecessaire si aucun r'esultat pr'e-calcul'e n est disponible.',\ncall. = FALSE\n)\n}\n\nif (!is.list(res_textual_prep_classes) ||\n!is.list(res_group_profile_classes)) {\nstop(\n'Les artefacts attendus ne sont pas disponibles sous forme de listes. ',\n'V'erifie que la case 16 a bien 'et'e ex'ecut'ee avec NaileR install'e.',\ncall. = FALSE\n)\n}\n\nres_contextualized_classes <- tryCatch(\nNaileR::nail_textual_contextualized(\ngroup_profile_prep = res_group_profile_classes,\ntextual_prep = res_textual_prep_classes,\ninterpretation_mode = 'comparative',\nmodel = 'llama3',\ngenerate = FALSE\n),\nerror = function(e) {\npaste(\n'nail_textual_contextualized() non ex'ecut'e :',\nconditionMessage(e)\n)\n}\n)\n}\n\n# V'erifier le mode de production\n\ngeneration_precalculee\nclass(res_contextualized_classes)\n\n# Pr'esenter le principe de contextualisation\n\nflow_contextualisation_classes <- data.frame(\nsource = c(\n'Verbatims',\n'Variables structur'ees',\n'Synth`ese contextualis'ee'\n),\nobjet_R = c(\n'res_textual_prep_classes',\n'res_group_profile_classes',\n'res_contextualized_classes'\n),\nrole = c(\n'faire 'emerger les th`emes et formulations associ'es aux classes',\n'd'ecrire les classes `a partir des variables du questionnaire',\n'combiner les deux sources pour interpr'eter les classes'\n),\nstringsAsFactors = FALSE\n)\n\nflow_contextualisation_classes\n\n# Fonction utilitaire pour retrouver un champ textuel dans un objet imbriqu'e\n\ntrouver_champ_texte <- function(objet, champs, profondeur = 0) {\n\nif (profondeur > 3) {\nreturn(NULL)\n}\n\nif (is.list(objet)) {\n\nnoms <- names(objet)\n\nif (!is.null(noms)) {\n  champ_direct <- intersect(champs, noms)\n\n  if (length(champ_direct) > 0) {\n    return(objet[[champ_direct[1]]])\n  }\n}\n\nfor (element in objet) {\n  resultat <- trouver_champ_texte(\n    element,\n    champs = champs,\n    profondeur = profondeur + 1\n  )\n\n  if (!is.null(resultat)) {\n    return(resultat)\n  }\n}\n\n}\n\nNULL\n}\n\nextraire_champ_texte <- function(objet, champs) {\n\nchamp <- trouver_champ_texte(\nobjet = objet,\nchamps = champs\n)\n\nif (is.null(champ)) {\ntexte <- paste(\ncapture.output(str(objet, max.level = 2)),\ncollapse = '\n'\n)\n} else {\ntexte <- paste(\nas.character(champ),\ncollapse = '\n'\n)\n}\n\ntexte <- gsub(\npaste0(intToUtf8(92), 'n'),\n'\n',\ntexte,\nfixed = TRUE\n)\n\ntexte <- gsub(\npaste0(intToUtf8(92), 't'),\n'\t',\ntexte,\nfixed = TRUE\n)\n\ntexte\n}\n\n# Extraire le prompt ou l objet pr'epar'e\n\ntexte_prompt_contextualized <- extraire_champ_texte(\nres_contextualized_classes,\nchamps = c(\n'prompt',\n'prompts',\n'request',\n'instruction',\n'instructions'\n)\n)\n\nsubstr(texte_prompt_contextualized, 1, 2000)\nnchar(texte_prompt_contextualized)\n\n# Extraire la r'eponse ou l interpr'etation g'en'er'ee si elle existe\n\ntexte_reponse_contextualized <- extraire_champ_texte(\nres_contextualized_classes,\nchamps = c(\n'response',\n'answer',\n'result',\n'interpretation',\n'summary',\n'text'\n)\n)\n\nsubstr(texte_reponse_contextualized, 1, 2500)\nnchar(texte_reponse_contextualized)",
                                                          expected_output = "Un objet `res_contextualized_classes` combinant profils textuels et profils structur'es des classes.",
