  clean_taidyverse_embedded_code <- function(x) {
    if (is.null(x) || !is.character(x)) {
      return(x)
    }

    # Pseudo-accents graves : `a, `e, etc.
    x <- gsub(
      "`([[:alpha:]])",
      "\\1",
      x,
      perl = TRUE
    )

    # Pseudo-accents circonflexes : ^e, ^a, etc.
    x <- gsub(
      "\\^([[:alpha:]])",
      "\\1",
      x,
      perl = TRUE
    )

    # Apostrophes entre deux lettres :
    # cre'e -> cree ; donn'ees -> donnees ; tronqu'ee -> tronquee.
    x <- gsub(
      "(?<=[[:alpha:]])'+(?=[[:alpha:]])",
      "",
      x,
      perl = TRUE
    )

    # Cas du type : a 'ete, interactions 'eventuelles.
    x <- gsub(
      "([[:alpha:]])([[:space:]])'+([eE][[:alpha:]]*)",
      "\\1\\2\\3",
      x,
      perl = TRUE
    )

    # Echappements invalides éventuellement présents : \e, \E, etc.
    x <- gsub(
      "\\\\(?=[eEaAiIoOuUyY])",
      "",
      x,
      perl = TRUE
    )

    x
  }

  steps <- lapply(steps, function(step) {
    step$code <- clean_taidyverse_embedded_code(step$code)

    if (!is.null(step$code_display)) {
      step$code_display <- clean_taidyverse_embedded_code(step$code_display)
    }

    step
  })

  step_ids <- vapply(steps, function(x) x$id, character(1))
  names(steps) <- step_ids

  steps
}
